INSERT INTO pantry_recipe_steps ("id", "recipe_id", "step_order", "title", "description", "image_url") VALUES
  ('443c35d1-f661-43ba-b7ff-9dbdfe7023cd', '189b8497-dd45-4231-b193-6423ac1e1b30', 1, 'Make the broth base', 'In a pot, bring 1.5 cups (375ml) of water to a boil over medium-high heat (5 mins) with minced garlic (5g), gochugaru (7g), and soy sauce (7.5ml).', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/altang-step1.png'),
  ('fd2ef0db-1934-4ce5-bfe8-d022a8ea0063', '189b8497-dd45-4231-b193-6423ac1e1b30', 2, 'Add roe & tofu', 'Gently add the fish roe (100g), firm tofu (75g), and sliced mushrooms (40g, if using) into the boiling broth.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/altang-step2.png'),
  ('6c383242-5c3a-4520-abf9-f99a8f1a95aa', '189b8497-dd45-4231-b193-6423ac1e1b30', 3, 'Simmer', 'Reduce heat to medium and simmer gently for 10 minutes until the fish roe is fully cooked through.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/altang-step3.png'),
  ('0f41c465-76b6-4ced-9ffb-a6653adb5e09', '189b8497-dd45-4231-b193-6423ac1e1b30', 4, 'Garnish & serve', 'Stir in the chopped green onions (15g) and a drizzle of perilla oil (2.5ml, if using). Serve hot.', NULL),
  ('fa5c0658-4bd0-4faa-aee0-e84e3a9a66e1', '3f7ce242-c084-494e-bde1-e6c1e2872644', 1, 'Arrange ingredients', 'Arrange sliced Spam (67g), chopped kimchi (50g), firm tofu (50g), sliced mushrooms (33g), and soaked rice cakes (50g) side by side in a small pot.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/budae-jjigae-step1.png'),
  ('2d5b7170-b947-4fbc-8dd9-b488c177de17', '3f7ce242-c084-494e-bde1-e6c1e2872644', 2, 'Mix the broth', 'In a small bowl, whisk together gochujang (10g), gochugaru (2.3g), and soy sauce (5ml) with 1 cup (250ml) of water, then pour the mixture evenly over the ingredients in the pot.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/budae-jjigae-step2.png'),
  ('7cd36fc7-c60b-4206-abac-d4b34213fc95', '3f7ce242-c084-494e-bde1-e6c1e2872644', 3, 'Simmer the stew', 'Bring the stew to a boil over medium-high heat, then reduce heat to medium and cook for 15 minutes until all ingredients are tender and cooked through.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/budae-jjigae-step3.png'),
  ('14873508-749e-47cc-835d-d70b92770742', '3f7ce242-c084-494e-bde1-e6c1e2872644', 4, 'Garnish & serve', 'Garnish with chopped green onions (10g). Mix lightly and eat directly from the pot.', NULL),
  ('00f937ac-1f41-4e84-862f-40844dd1d774', 'a6d7b7a4-8d6d-4621-9fe0-2c805dc6f1a6', 1, 'Arrange ingredients', 'Arrange the sliced Spam (67g), chopped kimchi (50g), firm tofu (50g), mushrooms (33g), and rice cakes (50g) in a wide pot.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/budae-jjigae-deluxe-step1.png'),
  ('3612109f-3e1b-420e-a0af-32f8c23de277', 'a6d7b7a4-8d6d-4621-9fe0-2c805dc6f1a6', 2, 'Add seasoned broth', 'Mix gochujang (10g) and soy sauce (5ml) with 1 cup (250ml) of water, and pour the mixture over the arranged ingredients.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/budae-jjigae-deluxe-step2.png'),
  ('7fdf2b90-8f15-4e52-946c-36aa1a00614c', 'a6d7b7a4-8d6d-4621-9fe0-2c805dc6f1a6', 3, 'Cook the stew', 'Bring to a boil over medium-high heat and cook for 15 minutes.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/budae-jjigae-deluxe-step3.png'),
  ('19134f80-a81b-4e1a-961a-9ab081f75e4d', 'a6d7b7a4-8d6d-4621-9fe0-2c805dc6f1a6', 4, 'Top with cheese & serve', 'Place the slice of American cheese (10g) on top to melt from the residual heat, garnish with chopped green onions (10g, if using), and serve.', NULL),
  ('947a1d99-f91d-40db-97d8-93351cb73907', 'a2a7f715-d62f-4fe4-8839-5a128dbe149f', 1, 'Marinate the chicken', 'In a mixing bowl, combine the boneless skinless chicken thigh pieces (200g) with gochujang (22.5g), gochugaru (3.5g), soy sauce (15ml), and minced garlic (7.5g) to marinate.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/dakgalbi-jjigae-step1.png'),
  ('24dcaf58-73cf-4b0e-b141-2065e6cf31e9', 'a2a7f715-d62f-4fe4-8839-5a128dbe149f', 2, 'Transfer to pot', 'Transfer the marinated chicken to a pot along with the diced potato (75g) and sliced onion (40g). Add 0.75 cup (180ml) of water.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/dakgalbi-jjigae-step2.png'),
  ('f28b1672-0d13-48b1-8fa3-fab3b99bcef6', 'a2a7f715-d62f-4fe4-8839-5a128dbe149f', 3, 'Simmer the stew', 'Bring to a boil over medium-high heat (5 mins), then cover, reduce heat to medium-low, and simmer for 20 minutes until the chicken and potatoes are thoroughly cooked.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/dakgalbi-jjigae-step3.png'),
  ('8c12b6da-58d9-430c-ac35-defda42f06e3', 'a2a7f715-d62f-4fe4-8839-5a128dbe149f', 4, 'Reduce & garnish', 'Uncover and cook for 3 more minutes to slightly thicken the sauce. Garnish with chopped green onions (15g) before serving.', NULL),
  ('dac8ffba-4a22-413f-9123-28226487cdde', 'a92aa661-1cdd-4448-a065-854d200a1c29', 1, 'Bring broth to boil', 'Bring 1 cup (250ml) of water or anchovy broth to a boil in a pot over medium-high heat (5 mins).', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/doenjang-jjigae-step1.png'),
  ('979e094c-e509-4732-8b26-cad5dbcb73c0', 'a92aa661-1cdd-4448-a065-854d200a1c29', 2, 'Dissolve doenjang', 'Dissolve the doenjang (15g) completely into the boiling broth, then add the minced garlic (2.5g).', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/doenjang-jjigae-step2.png'),
  ('55c6e6bb-eff0-4412-aee0-c12335f1cc56', 'a92aa661-1cdd-4448-a065-854d200a1c29', 3, 'Add vegetables', 'Add the diced onions (40g), zucchini (40g), and sliced mushrooms (50g) to the pot. Simmer on medium heat for 10 minutes.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/doenjang-jjigae-step3.png'),
  ('a1db3f56-6d94-40f2-8573-70696b2499e2', 'a92aa661-1cdd-4448-a065-854d200a1c29', 4, 'Add tofu & finish', 'Add the cubed firm tofu (100g) and simmer for 5 more minutes. Garnish with chopped green onions (7.5g) and serve hot.', NULL),
  ('21a5f5fc-7ac7-40e8-a8fa-4dd27dbed8b3', 'f1ed7f7a-e71b-495c-bdd3-8be5bf96e808', 1, 'Prepare the broth', 'Bring the anchovy broth (250ml) to a boil in a pot over medium-high heat (5 mins). Dissolve the doenjang (15g) into the broth along with the minced garlic (5g).', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/doenjang-sundubu-jjigae-step1.png'),
  ('c39b182b-5417-4af7-8916-c9366a3c58e5', 'f1ed7f7a-e71b-495c-bdd3-8be5bf96e808', 2, 'Add vegetables & tofu', 'Add the diced zucchini (20g), sliced mushrooms (40g), and soft tofu (150g, gently spooned in) to the pot.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/doenjang-sundubu-jjigae-step2.png'),
  ('42b03d8b-c733-4f64-b1e7-9632e4f2fa61', 'f1ed7f7a-e71b-495c-bdd3-8be5bf96e808', 3, 'Simmer', 'Simmer on medium heat for 8 minutes.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/doenjang-sundubu-jjigae-step3.png'),
  ('a08192a1-c0ec-4331-a328-a164eba596da', 'f1ed7f7a-e71b-495c-bdd3-8be5bf96e808', 4, 'Add egg & garnish', 'If using an egg (1), crack it directly into the bubbling stew and cook for 1 minute. Garnish with chopped green onions (7.5g) and serve.', NULL),
  ('80884cf0-6a8f-4149-916a-fa9c58378055', '79991c0f-4a60-4fb2-8a8c-d07142f4b9f7', 1, 'Soak the ribs', 'Soak the beef short ribs (200g) in cold water for 1 hour to draw out any blood. Drain thoroughly.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/galbitang-step1.png'),
  ('1df4c647-8c77-4c84-9c01-36a3d8ac16bf', 'eaeed762-8fa6-4f84-ad6e-c27f6dc95194', 1, 'Make the sauce', 'In a small bowl, mix gochujang (1 tbsp) and sesame oil (0.5 tbsp) together.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/bibim-gimbap-step1.png'),
  ('b4ea8ee3-4729-43db-8ea7-19bda0b747d6', 'eaeed762-8fa6-4f84-ad6e-c27f6dc95194', 2, 'Make egg strips', 'Crack the egg (1) into a bowl, whisk thoroughly, pour into a skillet heated to 170°C with a few drops of oil, cook for 1.5 minutes per side, and cut into thin strips.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/bibim-gimbap-step2.png'),
  ('ba6e0989-c779-4e8f-bfe7-010a3c3b7fd6', 'eaeed762-8fa6-4f84-ad6e-c27f6dc95194', 3, 'Blanch the spinach', 'Blanch the spinach (50g) in boiling water for 30 seconds, rinse under cold water, squeeze out all excess moisture, and set aside.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/bibim-gimbap-step3.png'),
  ('d28a4cd1-90d2-48e3-991c-21c0b806a92c', '79991c0f-4a60-4fb2-8a8c-d07142f4b9f7', 2, 'Blanch the ribs', 'Blanch the ribs in a pot of boiling water for 3 minutes, then drain and rinse completely under cold running water.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/galbitang-step2.png'),
  ('6b2c4fc9-0cae-47b6-911f-20ef1d63f0c0', '79991c0f-4a60-4fb2-8a8c-d07142f4b9f7', 3, 'Slow simmer', 'Return the cleaned ribs to a large pot with 3 cups (750ml) of clean water, minced garlic (6g), and quartered onion (50g). Bring to a boil over high heat, then reduce heat to low and simmer covered for 1 hour until the beef is tender.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/galbitang-step3.png'),
  ('f0003001-5317-4180-948d-5e49270b74c1', '79991c0f-4a60-4fb2-8a8c-d07142f4b9f7', 4, 'Season & serve', 'Remove the onion pieces, season the clear broth with salt (1.5g), ladle into a bowl, garnish with chopped green onions (11g), and finish with a drop of sesame oil (1.2ml, if using).', NULL),
  ('0ecb5791-3379-43c6-ad09-d55e9e235513', 'f9d4dc71-a9f5-4444-a7fd-19464be2d04d', 1, 'Blanch the bones', 'Blanch the pork neck bones (150g) in a pot of boiling water for 5 minutes, then drain and rinse thoroughly under cold water.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/gamja-tang-step1.png'),
  ('ea4615ad-d36c-4415-814a-f4fbf1d42d20', 'f9d4dc71-a9f5-4444-a7fd-19464be2d04d', 2, 'Simmer the broth', 'Place the clean bones into a pot with 1.5 cups (375ml) of water and minced garlic (6g). Bring to a boil, then simmer over medium-low heat for 30 minutes.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/gamja-tang-step2.png'),
  ('a65d0f03-4e8b-4cb3-b5f2-b5bb0db69c2c', 'f9d4dc71-a9f5-4444-a7fd-19464be2d04d', 3, 'Add seasoning & potato', 'Add the gochugaru (5g), doenjang (3.75g), and potato chunks (100g) to the pot. Simmer for another 20 minutes until the potatoes are fork-tender.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/gamja-tang-step3.png'),
  ('b8ad6e95-5582-49f3-b5c7-e6a551617605', 'f9d4dc71-a9f5-4444-a7fd-19464be2d04d', 4, 'Garnish & serve', 'Drizzle with perilla oil (3.75ml, if using) and garnish with chopped green onions (11g) and sesame seeds (0.25g, if using) before serving.', NULL),
  ('0aae1b4a-8154-478a-920c-f0304064ee75', '664c5f84-e0a1-467f-b67d-2861a40df74c', 1, 'Stir-fry pork', 'Heat a pot over medium-high heat with 1 tsp of oil. Stir-fry the sliced pork (100g) with minced garlic (5g) and gochujang (22.5g) for 2 minutes.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/gochujang-jjigae-step1.png'),
  ('962d238e-42a3-4be2-9fb0-05fe0f9845a9', '664c5f84-e0a1-467f-b67d-2861a40df74c', 2, 'Add water & veg', 'Pour 1 cup (250ml) of water into the pot, add the diced potatoes (50g) and zucchini (40g). Bring to a boil, then reduce heat to medium and simmer for 15 minutes.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/gochujang-jjigae-step2.png'),
  ('864ffa7b-0eb4-4973-a49c-02f0c25d4041', '664c5f84-e0a1-467f-b67d-2861a40df74c', 3, 'Add tofu', 'Add the cubed firm tofu (75g) and sliced mushrooms (40g, if using) to the pot. Cook for 5 more minutes.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/gochujang-jjigae-step3.png'),
  ('f824e027-bd0e-4800-b623-80e9046e16c5', '664c5f84-e0a1-467f-b67d-2861a40df74c', 4, 'Garnish & serve', 'Garnish with chopped green onions (7.5g) and serve hot.', NULL),
  ('a2c32394-ebbf-46aa-9600-b632c2e1c686', 'e7ec4015-7127-4dac-b7d3-627263a8cc10', 1, 'Boil the beef', 'Boil the beef (100g) in 1.5 cups (375ml) of water for 25 minutes until tender. Remove the beef, slice it thinly, and reserve the broth.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/haejang-guk-step1.png'),
  ('a88c897d-a712-4978-870a-3c759fb0eade', 'e7ec4015-7127-4dac-b7d3-627263a8cc10', 2, 'Season the broth', 'Add the bean sprouts (100g), doenjang (7.5g), gochugaru (3.5g), minced garlic (7.5g), and soy sauce (7.5ml) into the reserved beef broth. Bring to a boil, then simmer on medium heat for 15 minutes.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/haejang-guk-step2.png'),
  ('3251fba1-8f5e-45f7-89c9-04c6ab468694', 'e7ec4015-7127-4dac-b7d3-627263a8cc10', 3, 'Return beef & egg', 'Return the sliced beef to the pot. If using an egg (1), crack it gently into the soup and cook for 2 minutes.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/haejang-guk-step3.png'),
  ('88c61c37-763a-400d-8ff4-81aa6d31766c', 'e7ec4015-7127-4dac-b7d3-627263a8cc10', 4, 'Garnish & serve', 'Garnish with chopped green onions (15g) and serve hot.', NULL),
  ('79fcfe4e-a9a3-43d2-bd65-9d1bdcc0c69f', '61e7d46c-b44b-43be-8357-bd844f347f2e', 1, 'Prepare the broth', 'Bring the anchovy broth (250ml) to a boil in a pot over medium-high heat (5 mins). Dissolve the doenjang (15g) into the broth along with minced garlic (5g).', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/haemul-doenjang-jjigae-step1.png'),
  ('2b390042-3e3c-48ec-94e1-3251e741b9ba', '61e7d46c-b44b-43be-8357-bd844f347f2e', 2, 'Add seafood & tofu', 'Add the diced zucchini (40g), seafood mix (100g), and firm tofu (75g) to the pot.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/haemul-doenjang-jjigae-step2.png'),
  ('1e48c03c-ba36-485e-a90b-1da5d0855b34', '61e7d46c-b44b-43be-8357-bd844f347f2e', 3, 'Simmer', 'Simmer on medium heat for 12 minutes until the seafood is fully cooked through.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/haemul-doenjang-jjigae-step3.png'),
  ('69f768c8-9672-48a6-b2cb-38b759983496', '61e7d46c-b44b-43be-8357-bd844f347f2e', 4, 'Garnish & serve', 'Garnish with chopped green onions (7.5g) and a pinch of gochugaru (1g, if using) before serving.', NULL),
  ('c4693d95-4c50-49f9-966b-cd7bcf1b00cc', '80dffcd8-cbd9-4d70-821a-ceadfb603ace', 1, 'Make spicy oil base', 'Heat a small pot over medium heat with sesame oil (2.5ml, if using) or 1 tsp of cooking oil. Sauté the minced garlic (5g) and gochugaru (7g) for 1 minute to create a spicy oil base.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/haemul-sundubu-jjigae-step1.png'),
  ('a41a15d7-11bb-448f-9a36-f91669308b97', '80dffcd8-cbd9-4d70-821a-ceadfb603ace', 2, 'Add seafood & broth', 'Add the seafood mix (100g) and stir-fry briefly for 1 minute. Pour in 0.75 cup (180ml) of water and soy sauce (7.5ml). Bring to a boil.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/haemul-sundubu-jjigae-step2.png'),
  ('49f140b5-e75a-49fb-ba44-5c120510fc05', '80dffcd8-cbd9-4d70-821a-ceadfb603ace', 3, 'Add soft tofu', 'Gently add the soft tofu (150g) into the broth, breaking it up lightly with a spoon, and simmer for 5 minutes.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/haemul-sundubu-jjigae-step3.png'),
  ('fef2fefb-1973-492d-987d-19ea7effdf46', '80dffcd8-cbd9-4d70-821a-ceadfb603ace', 4, 'Crack egg & serve', 'Crack an egg (1) directly into the bubbling stew, cook for 1 minute until the white sets, garnish with chopped green onions (7.5g), and serve.', NULL),
  ('ff06b91c-8572-40f3-96d3-5581452320b5', 'a3f2157c-b47e-4857-baeb-b658eb3242d1', 1, 'Boil kimchi broth', 'In a pot, combine chopped fermented kimchi (80g), minced garlic (2.5g), and 1.5 cups (375ml) of water. Bring to a boil over medium-high heat, then reduce heat and simmer for 10 minutes.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/kimchi-guk-step1.png'),
  ('937c836c-1c4e-4c7e-94ee-9bec7af3cb47', 'a3f2157c-b47e-4857-baeb-b658eb3242d1', 2, 'Add tofu', 'Add the cubed firm tofu (75g) and soy sauce (7.5ml) to the pot. Cook for 5 more minutes.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/kimchi-guk-step2.png'),
  ('cbe9eeaa-d91b-4e9f-b956-1635c4fd7c74', 'a3f2157c-b47e-4857-baeb-b658eb3242d1', 3, 'Season & serve', 'Turn off the heat, drizzle with sesame oil (2.5ml, if using), and garnish with chopped green onions (7.5g) and gochugaru (1g, if using) before serving.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/kimchi-guk-step3.png'),
  ('fadb8dfe-180f-4470-a737-a43f5327c9c1', 'aa53faef-6a75-4534-ba34-8735739053b4', 1, 'Brown the pork', 'Heat a pot over medium-high heat with 1 tsp of oil and stir-fry the sliced pork (75g) until lightly browned.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/kimchi-jjigae-step1.png'),
  ('89f1b931-cdbc-4452-addd-b79f17626d90', 'aa53faef-6a75-4534-ba34-8735739053b4', 2, 'Add kimchi', 'Add the chopped fermented kimchi (120g) and gochugaru (3.5g) to the pot. Stir-fry together for 2 minutes until the kimchi softens.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/kimchi-jjigae-step2.png'),
  ('47dcfe13-b6b1-46d9-81e4-210f2bb27dbb', 'aa53faef-6a75-4534-ba34-8735739053b4', 3, 'Simmer the stew', 'Pour in 1 cup (250ml) of water and soy sauce (7.5ml). Bring to a boil over high heat, then reduce heat to medium and simmer for 15 minutes.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/kimchi-jjigae-step3.png'),
  ('6677e3df-cbbe-43a6-82c9-91c8106732aa', 'aa53faef-6a75-4534-ba34-8735739053b4', 4, 'Add tofu & serve', 'Add the cubed firm tofu (100g) and simmer for 5 more minutes. Drizzle with sesame oil (2.5ml, if using) and garnish with chopped green onions (7.5g) before serving.', NULL),
  ('fcf36837-7d29-44ba-8a32-5ea4613a1723', 'a328a653-e7f3-4339-bd02-fb82d6bc945b', 1, 'Fry the Spam', 'Cut the Spam (100g) into small cubes. In a pot over medium-high heat, lightly fry the Spam cubes for 2 minutes until golden on the edges.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/kimchi-stew-with-spam-step1.png'),
  ('e2f18dbc-af34-43ee-950f-7241f9cbb1b3', 'a328a653-e7f3-4339-bd02-fb82d6bc945b', 2, 'Add kimchi', 'Add the chopped fermented kimchi (120g) and gochugaru (3.5g) directly into the pot with the Spam. Stir-fry for 2 minutes.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/kimchi-stew-with-spam-step2.png'),
  ('2b537b92-016f-4bd4-8a3f-b38a6cc9933d', 'a328a653-e7f3-4339-bd02-fb82d6bc945b', 3, 'Simmer the stew', 'Pour in 1 cup (250ml) of water and soy sauce (7.5ml). Bring to a boil, then reduce heat to medium and simmer for 15 minutes.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/kimchi-stew-with-spam-step3.png'),
  ('b5e10175-e429-4589-ade3-4eea7fa18822', 'a328a653-e7f3-4339-bd02-fb82d6bc945b', 4, 'Add tofu & serve', 'Add the cubed firm tofu (75g) and simmer for 5 more minutes. Top with chopped green onions (7.5g) and serve hot.', NULL),
  ('5c460add-33bd-44ff-b891-9b2e13dbaccb', '15f639de-b319-4756-bb87-5810676d3eaf', 1, 'Sauté kimchi & pork', 'Heat a pot over medium-high heat with 1 tsp of oil. Sauté the chopped kimchi (40g), minced garlic (5g), and sliced pork (50g, if using) for 3 minutes.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/kimchi-sundubu-jjigae-step1.png'),
  ('abb21844-264b-41b8-900c-ad3aacd53c80', '15f639de-b319-4756-bb87-5810676d3eaf', 2, 'Add water & gochugaru', 'Pour in 0.75 cup (180ml) of water and soy sauce (7.5ml). Bring to a boil, then add the gochugaru (3.5g).', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/kimchi-sundubu-jjigae-step2.png'),
  ('4e7b0829-6768-41cc-8a5f-35354bc12edc', '15f639de-b319-4756-bb87-5810676d3eaf', 3, 'Add soft tofu', 'Gently slide in the soft tofu (150g) and simmer for 5 minutes.', NULL),
  ('ea3b5f40-f67a-44e0-a051-e8584db29726', '15f639de-b319-4756-bb87-5810676d3eaf', 4, 'Crack egg & serve', 'Crack an egg (1, if using) into the stew and cook for 1 minute. Garnish with chopped green onions (7.5g) and serve.', NULL),
  ('220bfc65-dfc5-4865-b44b-b1fbff31635a', '931c0795-c560-4370-8f03-48cb6517136f', 1, 'Blanch the oxtail', 'Blanch the oxtail pieces (250g) in a pot of boiling water for 5 minutes, then drain and rinse thoroughly under cold water.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/kkori-gomtang-step1.png'),
  ('333d9c8f-92a3-4e06-bdc6-2f1b49a1fdb1', '931c0795-c560-4370-8f03-48cb6517136f', 2, 'Slow simmer', 'Place the cleaned oxtail in a large pot with 3 cups (750ml) of water, minced garlic (6g), and quartered onion (50g). Bring to a boil, then reduce heat to low and simmer covered for 2.5 to 3 hours until the meat falls off the bone.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/kkori-gomtang-step2.png'),
  ('89395067-ad9a-49de-a212-1f7377c05166', '931c0795-c560-4370-8f03-48cb6517136f', 3, 'Season the broth', 'Discard the onion pieces. Season the rich broth with salt (1.5g).', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/kkori-gomtang-step3.png'),
  ('99bfdfc3-41d4-4341-99c6-23abfcc4e5c0', '931c0795-c560-4370-8f03-48cb6517136f', 4, 'Garnish & serve', 'Ladle into a bowl, garnish with chopped green onions (11g), add a drop of sesame oil (1.2ml, if using), and serve hot with rice.', NULL),
  ('1293d6ed-b461-422d-9a4c-972c2d41d952', 'fefd856b-6764-44c1-bb41-3cc579b42901', 1, 'Sauté pork & kimchi', 'Heat a pot over medium-high heat with sesame oil (2.5ml). Sauté the sliced pork (50g), minced garlic (5g), and chopped kimchi (40g) for 3 minutes.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/kongbiji-jjigae-step1.png'),
  ('a895b277-ca2b-40a0-9dc7-893d254d0f65', 'fefd856b-6764-44c1-bb41-3cc579b42901', 2, 'Add soybean pulp', 'Add the soybean pulp (150g) and 0.5 cup (125ml) of water to the pot. Stir well and simmer for 15 minutes over medium-low heat, stirring frequently to prevent sticking at the bottom.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/kongbiji-jjigae-step2.png'),
  ('264d7e87-90d4-4ec8-a02e-8c069c803d89', 'fefd856b-6764-44c1-bb41-3cc579b42901', 3, 'Season the stew', 'Season with soy sauce (7.5ml) and add gochugaru (1g, if using) for extra heat.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/kongbiji-jjigae-step3.png'),
  ('42a21c51-2d44-45e8-90f7-d6bc23e3e868', 'fefd856b-6764-44c1-bb41-3cc579b42901', 4, 'Garnish & serve', 'Garnish with chopped green onions (7.5g) and serve hot.', NULL),
  ('015024c5-72d9-4538-86cf-ed9e6ccc87f0', 'a0038947-6e56-4500-ac97-8de0cf25b92c', 1, 'Soak the seaweed', 'Soak the dried seaweed (15g) in cold water for 20 minutes until fully expanded. Drain thoroughly and cut into bite-sized pieces using kitchen shears.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/miyeok-guk-step1.png'),
  ('0eb48e1f-2869-4be2-9bfc-d3a2f1086045', 'a0038947-6e56-4500-ac97-8de0cf25b92c', 2, 'Stir-fry beef', 'Heat a pot over medium-high heat with sesame oil (7.5ml). Add the sliced beef (75g) and stir-fry for 2 minutes until color changes.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/miyeok-guk-step2.png'),
  ('35531ea0-63a4-4e8b-8c1a-9436c137170b', 'a0038947-6e56-4500-ac97-8de0cf25b92c', 3, 'Add seaweed & soy sauce', 'Add the soaked seaweed and soy sauce (15ml) into the pot, continuing to stir-fry together for another 2 minutes.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/miyeok-guk-step3.png'),
  ('0a8962c1-fb39-460f-be81-aa24d2138f2e', 'a0038947-6e56-4500-ac97-8de0cf25b92c', 4, 'Simmer & season', 'Pour in 2 cups (500ml) of water and minced garlic (5g). Bring to a boil, then reduce heat to medium and simmer for 20 minutes. Season with salt (3g) and garnish with chopped green onions (7.5g, if using).', NULL),
  ('244823b4-3e32-40f1-b327-d37707bac0ec', '3e34fe2b-3871-4691-ae64-c96fd7ec89ea', 1, 'Prep the chicken', 'Thoroughly rinse the small whole chicken (1 small) inside and out, trimming excess fat.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/samgyetang-step1.png'),
  ('bff8c8ec-a384-48c4-98dd-d3c3692bbd24', '3e34fe2b-3871-4691-ae64-c96fd7ec89ea', 2, 'Stuff the chicken', 'Stuff the cavity of the chicken tightly with uncooked rice (45g), peeled garlic cloves (15g), ginseng root (0.5 root, if using), and jujubes (2 pieces, if using). Secure the opening with a toothpick or kitchen twine.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/samgyetang-step2.png'),
  ('71638c0d-7a1e-4dab-a5fe-de3249086061', '3e34fe2b-3871-4691-ae64-c96fd7ec89ea', 3, 'Bring to boil', 'Place the stuffed chicken in a deep pot and cover completely with water (about 4 cups/1L). Bring to a rolling boil over high heat (10 mins).', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/samgyetang-step3.png'),
  ('ecce32f9-9bb8-435e-897b-ebc332fb8dc5', 'eaeed762-8fa6-4f84-ad6e-c27f6dc95194', 4, 'Sauté the carrots', 'Sauté the julienned carrots (25g) in a pan with 0.5 tsp of oil over medium heat for 2 minutes until tender.', NULL),
  ('50ecb8c1-cdea-4dde-8f54-eb1416ab1ab4', '3e34fe2b-3871-4691-ae64-c96fd7ec89ea', 4, 'Simmer & season', 'Reduce heat to low, cover the pot, and simmer gently for 1 hour until the chicken is exceptionally tender and the broth is rich. Season with salt (3g), garnish with chopped green onions (15g), and serve hot.', NULL),
  ('230b50c4-01da-42c1-bed9-2e55be10b782', '70d24535-a2af-4b28-b80f-454c88aad0fa', 1, 'Slice beef & radish', 'Slice the beef (100g) into thin bite-sized pieces and cut the radish (100g) into thin bite-sized rectangular cubes.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/sogogi-muguk-step1.png'),
  ('438f474b-e735-4bbc-8d61-daaa73791b1d', '70d24535-a2af-4b28-b80f-454c88aad0fa', 2, 'Sauté the beef', 'Heat a pot over medium-high heat with sesame oil (2.5ml). Sauté the beef with soy sauce (15ml) for 2 minutes until lightly browned.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/sogogi-muguk-step2.png'),
  ('01995635-cb51-41a0-bff0-9dd3123c664e', '70d24535-a2af-4b28-b80f-454c88aad0fa', 3, 'Add radish & water', 'Add the cubed radish and 2 cups (500ml) of water to the pot. Bring to a boil over high heat (5 mins).', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/sogogi-muguk-step3.png'),
  ('deb46c10-b497-401e-a563-ca74b1c4747a', '70d24535-a2af-4b28-b80f-454c88aad0fa', 4, 'Simmer & season', 'Reduce heat to medium and simmer for 20 minutes until the radish pieces are tender and translucent. Add minced garlic (5g) and season with salt (1.5g). Garnish with chopped green onions (7.5g) and serve.', NULL),
  ('ae7aa4c6-6982-4326-b280-8a4b32a73bf6', '684bba44-33c0-4e6b-a1d5-e03ec5ae9c8b', 1, 'Make spice base', 'Heat a small pot over medium heat with sesame oil (2.5ml). Sauté minced garlic (5g), gochugaru (7g), and sliced pork (50g, if using) for 1 minute to release aromatic flavors.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/sundubu-jjigae-step1.png'),
  ('9e1fa6eb-f245-4906-b88d-032aba36f99b', '684bba44-33c0-4e6b-a1d5-e03ec5ae9c8b', 2, 'Add broth', 'Pour in 0.75 cup (180ml) of water and soy sauce (7.5ml). Add sliced mushrooms (50g, if using) and bring to a boil over high heat (3 mins).', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/sundubu-jjigae-step2.png'),
  ('23442275-e9aa-432a-ab97-a8cb47220598', '684bba44-33c0-4e6b-a1d5-e03ec5ae9c8b', 3, 'Add soft tofu', 'Gently spoon the soft tofu (150g) into the boiling broth. Simmer for 5 minutes without stirring aggressively.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/sundubu-jjigae-step3.png'),
  ('bdb89030-1b4c-4a3f-9b61-d1f2a7e1dce0', '684bba44-33c0-4e6b-a1d5-e03ec5ae9c8b', 4, 'Crack egg & serve', 'Crack the egg (1) directly into the center of the stew and cook for 1 to 2 minutes until the white is set. Garnish with chopped green onions (7.5g) and serve immediately.', NULL),
  ('17165037-9c7e-4e13-b78c-9b608bd5e8da', 'd47eab3c-99df-4999-90ac-781f86052361', 1, 'Boil & shred beef', 'Boil the beef (133g) in 2 cups of water for 40 minutes until tender. Remove the beef, let cool slightly, and shred it by hand. Reserve the cooking broth.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/yukgaejang-step1.png'),
  ('cc40053a-22e8-4e6a-b6b2-33c4ee7badfa', 'd47eab3c-99df-4999-90ac-781f86052361', 2, 'Stir-fry in spices', 'Heat a pot over medium-high heat with sesame oil (10ml). Sauté gochugaru (7g) and minced garlic (6.5g) for 30 seconds, then add the shredded beef and toss to coat.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/yukgaejang-step2.png'),
  ('bb9ade9e-4fa9-4cf0-9508-b21032070ad8', 'd47eab3c-99df-4999-90ac-781f86052361', 3, 'Add broth & sprouts', 'Pour the reserved beef broth into the pot along with the bean sprouts (67g) and soy sauce (10ml). Bring to a boil, then reduce heat and simmer for 15 minutes.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/yukgaejang-step3.png'),
  ('ada295a7-1689-4a58-aa22-670715265422', 'd47eab3c-99df-4999-90ac-781f86052361', 4, 'Finish with egg', 'Stir in chopped green onions (15g). If using beaten eggs (0.67), drizzle them slowly into the soup and turn off the heat. Adjust seasoning and serve hot with rice.', NULL),
  ('7f761808-1a46-4cea-aecf-574ee5a31e64', 'eaeed762-8fa6-4f84-ad6e-c27f6dc95194', 5, 'Season the rice', 'Mix the cooked rice (1 cup/150g) thoroughly with the gochujang and sesame oil mixture.', NULL),
  ('0ce1d16e-3ee2-471f-a69a-4fa3a56c6468', 'eaeed762-8fa6-4f84-ad6e-c27f6dc95194', 6, 'Roll & serve', 'Place a seaweed sheet on a bamboo mat, spread the seasoned rice evenly over it leaving the top edge bare, add the egg strips, spinach, and carrots in a line, roll tightly, slice into rounds, and serve.', NULL),
  ('49c9c3a0-9558-4d60-8356-c80369d3bb1c', 'a14a1e4f-d8ee-4ca8-ac15-cb64011152f2', 1, 'Soak the noodles', 'Soak the glass noodles (100g) in warm water for 20 minutes to soften. Drain well and cut them in half with kitchen shears for easier eating.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/japchae-step1.png'),
  ('2871e7b6-f73e-4c90-a82b-3cbaa3e82e7e', 'a14a1e4f-d8ee-4ca8-ac15-cb64011152f2', 2, 'Blanch the spinach', 'Blanch the spinach (50g) in boiling water for 30 seconds, rinse under cold water, squeeze out all excess moisture, and toss with a pinch of salt.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/japchae-step2.png'),
  ('5e9cc333-607c-478f-bdbb-d38e05eac7b2', '8864f9c2-7932-41c3-b0de-5666e0831271', 6, 'Roll & slice', 'Roll the gimbap tightly, brush the outside with the remaining sesame oil (0.5 tbsp), slice into rounds, and serve.', NULL)
INSERT INTO pantry_recipe_steps ("id", "recipe_id", "step_order", "title", "description", "image_url") VALUES
  ('395e228b-4bdd-443a-8566-40d803a76e2a', '09e197dc-222f-49bd-9fad-61fce9953f76', 1, 'Soak the noodles', 'Soak glass noodles in cold water for 20 minutes to soften. Drain and set aside.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/andong-jjimdak-step1.png'),
  ('02026c64-9e96-455b-ac84-d5cf72cbd979', '09e197dc-222f-49bd-9fad-61fce9953f76', 2, 'Make the sauce', 'In a small bowl, whisk together: soy sauce (2 tbsp/30ml), sugar (1 tbsp/12g), minced garlic (1 tbsp/15g), and 150ml of water.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/andong-jjimdak-step2.png'),
  ('6110fa6a-56bd-495b-a029-b1e13731d33e', '09e197dc-222f-49bd-9fad-61fce9953f76', 3, 'Braise the chicken', 'Place chicken and sauce in a pan. Bring to a boil over medium-high heat (3 mins), then cover, reduce heat to medium-low, and simmer for 15 minutes.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/andong-jjimdak-step3.png'),
  ('9c30b287-0eb0-4b54-bebb-ff55661197be', '09e197dc-222f-49bd-9fad-61fce9953f76', 4, 'Add vegetables', 'Add potato, carrot, and onion to the pan. Cover and continue to simmer on medium-low heat for 12 minutes until vegetables are tender.', NULL),
  ('3535e819-58ef-416b-97ad-8b991a3c9f60', '09e197dc-222f-49bd-9fad-61fce9953f76', 5, 'Add noodles & finish', 'Add the soaked glass noodles, green onions, and gochugaru (if using). Simmer uncovered on medium heat for 5 minutes, stirring occasionally, until the sauce thickens and coats the chicken and noodles.', NULL),
  ('668fd7a2-7c90-415e-96df-e7b49de2dd36', 'f4a7f213-eb65-41eb-8fb6-1de460891984', 1, 'Make the marinade', 'In a bowl, thoroughly mix gochugaru (1.5 tbsp), gochujang (1 tbsp), soy sauce (1 tbsp), sugar (0.5 tbsp), minced garlic (1 tbsp), and sesame oil (0.5 tsp).', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/buldak-step1.png'),
  ('18763bcf-a0f1-4ac2-a2d9-075f8c9db7af', 'f4a7f213-eb65-41eb-8fb6-1de460891984', 2, 'Marinate the chicken', 'Add chicken pieces to the sauce. Mix well until evenly coated. Cover and refrigerate for at least 30 minutes.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/buldak-step2.png'),
  ('a6cde3ea-3d67-451b-8344-1cff3db7d1f1', 'f4a7f213-eb65-41eb-8fb6-1de460891984', 3, 'Cook the chicken', 'Heat a skillet over medium-high heat. Add chicken and cook for 8–10 minutes, stirring frequently, until fully cooked through and slightly charred.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/buldak-step3.png'),
  ('dbbcbd64-81a8-4afc-90b6-32aecd0169bc', 'f4a7f213-eb65-41eb-8fb6-1de460891984', 4, 'Add cheese & serve', 'If using cheese, sprinkle mozzarella over the chicken, cover the pan, and cook on low heat for 2 minutes until melted. Garnish with sliced green onion.', NULL),
  ('07bc1e68-29e9-419f-a34b-8e2139e7530e', '1adee2e9-10d5-4516-946e-abe7deea6fc5', 1, 'Make the marinade', 'In a bowl, mix soy sauce (1.5 tbsp), sugar (0.5 tbsp), minced garlic (0.5 tbsp), and sesame oil (0.5 tbsp).', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/bulgogi-step1.png'),
  ('255a6102-6f2d-44da-9201-0bc2edb8ea0e', '1adee2e9-10d5-4516-946e-abe7deea6fc5', 2, 'Marinate the beef', 'Combine the thinly sliced beef with the marinade and sliced onion. Toss well and let it sit for at least 15 minutes.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/bulgogi-step2.png'),
  ('64eceae7-a927-4f15-9aad-952a0f81239d', '1adee2e9-10d5-4516-946e-abe7deea6fc5', 3, 'Stir-fry', 'Heat a large skillet or wok over high heat. Add the marinated beef and onions (and mushrooms, if using). Stir-fry for 4–5 minutes until the beef is fully cooked and the sauce has caramelized.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/bulgogi-step3.png'),
  ('a444344a-92fd-40ec-9ee3-8e0d877779b8', '1adee2e9-10d5-4516-946e-abe7deea6fc5', 4, 'Garnish & serve', 'Remove from heat, garnish with chopped green onion and sesame seeds, and serve hot with steamed rice.', NULL),
  ('3f2eec94-5493-4917-a5b7-7a59b81742d9', 'a79a56b9-fbf0-441e-9bfc-b557f5bf6536', 1, 'Blanch the chicken', 'Bring a pot of water to a boil. Add the chicken pieces and blanch for 3 minutes to remove impurities. Drain and rinse under cold water.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/dak-bokkeum-tang-step1.png'),
  ('1810a41e-7aa6-4be1-904b-0f25e50885de', 'a79a56b9-fbf0-441e-9bfc-b557f5bf6536', 2, 'Make the sauce', 'In a small bowl, mix gochujang (1 tbsp), soy sauce (1 tbsp), sugar (0.5 tbsp), minced garlic (1 tbsp), and 200ml of water.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/dak-bokkeum-tang-step2.png'),
  ('4a6dc855-b65a-49f5-8759-8488ddcbc6d7', 'a79a56b9-fbf0-441e-9bfc-b557f5bf6536', 3, 'Simmer', 'Place blanched chicken, potatoes, and onions in a pot. Pour the sauce mixture over. Cover and simmer over medium-high heat for 15 minutes, then reduce heat to low and simmer for another 10 minutes.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/dak-bokkeum-tang-step3.png'),
  ('8e9790a2-12b5-4118-96c1-8790b643a989', 'a79a56b9-fbf0-441e-9bfc-b557f5bf6536', 4, 'Finish', 'Add the green onions and mushrooms (if using). Simmer for an additional 5 minutes without the lid to allow the sauce to thicken properly.', NULL),
  ('f274f791-339b-4bfc-aeb8-8641c02bc22f', '4003bed8-fc73-4f28-aa93-d6cf2839eccf', 1, 'Fry the chicken', 'Coat chicken pieces thoroughly in cornstarch. Heat oil in a pan to 170°C. Fry the chicken for 6–8 minutes until golden and crispy. Remove and drain on paper towels.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/dak-gangjeong-step1.png'),
  ('d6416f1c-1e1f-41eb-a5c2-6bfdf7f01514', '4003bed8-fc73-4f28-aa93-d6cf2839eccf', 2, 'Make the glaze', 'In a separate pan, combine gochujang (0.5 tbsp), sugar (1 tbsp), soy sauce (1 tbsp), minced garlic (1 tsp), vinegar (0.5 tbsp), and 1 tbsp of water. Cook on medium-low heat until bubbly and slightly thickened (2 minutes).', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/dak-gangjeong-step2.png'),
  ('ea788398-dacb-4619-8df2-b9f9a81a8e3b', '4003bed8-fc73-4f28-aa93-d6cf2839eccf', 3, 'Coat & serve', 'Add the fried chicken to the pan and toss quickly over low heat for 1 minute until completely coated in the glaze. Sprinkle with sesame seeds and serve.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/dak-gangjeong-step3.png'),
  ('f38fc7a6-fe61-42ce-a4a6-72ac47aef55d', '0bb849bd-1ace-4e9f-b224-9621d8c8813b', 1, 'Blanch the chicken', 'Bring a pot of water to a boil and add the chicken pieces. Blanch for 3 minutes, then drain and rinse thoroughly under cold water.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/dakdoritang-step1.png'),
  ('efab5e95-4736-4c24-920e-505bad0d592c', '0bb849bd-1ace-4e9f-b224-9621d8c8813b', 2, 'Make the sauce', 'In a bowl, mix together gochujang (1 tbsp), gochugaru (1 tbsp), soy sauce (1 tbsp), minced garlic (1 tbsp), and 200ml of water.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/dakdoritang-step2.png'),
  ('54372d86-4a64-47d7-b88a-d5b30038dd5f', '0bb849bd-1ace-4e9f-b224-9621d8c8813b', 3, 'Braise', 'Place the chicken, potatoes, and onions in a pot. Pour the sauce mixture over them. Bring to a boil over medium-high heat, then cover, reduce heat to medium-low, and simmer for 25 minutes.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/dakdoritang-step3.png'),
  ('117b3a4b-0601-4a16-857c-b8ac3fb6c878', '0bb849bd-1ace-4e9f-b224-9621d8c8813b', 4, 'Reduce & serve', 'Remove the lid and cook for another 5 minutes over medium heat to reduce the sauce slightly. Garnish with green onions and serve.', NULL),
  ('c7488a15-45b5-42d6-bcba-d8d1c92d6c18', 'cac5057c-ce58-4dd0-854f-36ef06ff9f2b', 1, 'Make the marinade', 'In a bowl, mix gochujang (1.5 tbsp), gochugaru (0.5 tbsp), soy sauce (1 tbsp), sugar (0.5 tbsp), and minced garlic (1 tbsp). Add the chicken pieces and coat well. Let it marinate for 20 minutes.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/dakgalbi-step1.png'),
  ('d74dfbd9-e5bc-4000-8da7-9a4ab899bf23', 'cac5057c-ce58-4dd0-854f-36ef06ff9f2b', 2, 'Cook the chicken', 'Heat a large pan over medium-high heat. Add the marinated chicken and stir-fry for 6–8 minutes until mostly cooked.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/dakgalbi-step2.png'),
  ('5ec64f02-2cc6-4752-95c0-b8552f9183f0', 'cac5057c-ce58-4dd0-854f-36ef06ff9f2b', 3, 'Add rice cakes & finish', 'Add the soaked rice cakes and sliced green onions. Stir-fry for another 3–4 minutes until the rice cakes are soft and the sauce is thick and caramelized around the chicken.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/dakgalbi-step3.png'),
  ('af07fe80-1435-4d0c-bfc4-d60d85c87176', '4f785fb8-c886-4359-b249-6cae60d36be1', 1, 'Marinate the ribs', 'Make small scores in the pork ribs. In a bowl, combine soy sauce (1.5 tbsp), sugar (1 tbsp), minced garlic (1 tbsp), sesame oil (0.5 tbsp), and grated onion (20g). Mix the ribs with the marinade and refrigerate for at least 1 hour.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/dwaeji-galbi-step1.png'),
  ('c9e55a4b-b1c9-4cf9-95d8-ce3faa551bdb', '4f785fb8-c886-4359-b249-6cae60d36be1', 2, 'Grill the ribs', 'Heat a pan over medium heat. Add the marinated ribs (with some marinade) and cook for 20–25 minutes, turning frequently to ensure even cooking and caramelization, until the sauce is sticky.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/dwaeji-galbi-step2.png'),
  ('50d06311-8c9d-4834-b1b7-8acfb001a875', '4f785fb8-c886-4359-b249-6cae60d36be1', 3, 'Garnish & serve', 'Remove from heat, garnish with sliced green onions and sesame seeds (if desired), and serve hot with rice.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/dwaeji-galbi-step3.png'),
  ('c01daf0a-8d6e-4598-b616-d4a8e75a7511', '84cdb55e-9030-4751-9132-fb5262af1acc', 1, 'Blanch the ribs', 'Boil the ribs in water for 5 minutes to remove impurities. Drain and rinse well under cold water. Score the meat with a knife.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/galbi-jjim-step1.png'),
  ('ac0c09c3-1a97-4e88-b897-74e1f5047d1c', '84cdb55e-9030-4751-9132-fb5262af1acc', 2, 'Braise the ribs', 'Place the ribs in a pot with soy sauce (1.5 tbsp), sugar (1 tbsp), minced garlic (1 tbsp), and 300ml of water. Bring to a boil, then reduce heat to low and simmer, covered, for 1 hour until the beef is tender.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/galbi-jjim-step2.png'),
  ('7175d431-5f77-42a5-a1b5-450dca623354', '84cdb55e-9030-4751-9132-fb5262af1acc', 3, 'Add vegetables', 'Add potato, carrot, and mushroom. Continue to cook for another 20 minutes until the vegetables are soft.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/galbi-jjim-step3.png'),
  ('895369a8-60f8-40b7-81f0-194441a0cca9', '84cdb55e-9030-4751-9132-fb5262af1acc', 4, 'Finish', 'Stir in the sesame oil (0.5 tbsp). Cook for an additional 5 minutes to let the sauce thicken. Garnish with green onions.', NULL),
  ('91006ef2-a821-4f49-9ab3-59f74575ae22', 'a8c7c721-68b7-44bd-b9da-815db0ea9140', 1, 'Make the batter', 'Whisk together flour (60g), salt (0.25 tsp), and 80ml of water until smooth. Stir in the seafood mix.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/haemul-pajeon-step1.png'),
  ('8859db78-49bf-4de4-87b1-37520093d8c3', 'a8c7c721-68b7-44bd-b9da-815db0ea9140', 2, 'Set up the pancake', 'Heat a pan with oil over medium-high heat. Lay the green onion stalks flat in the pan. Pour the batter and seafood mixture evenly over the onions. Pour the beaten egg over the top.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/haemul-pajeon-step2.png'),
  ('a1f67d88-bb27-4c86-a441-c83864b4d90b', 'a8c7c721-68b7-44bd-b9da-815db0ea9140', 3, 'Cook & serve', 'Cook for 4–5 minutes until the bottom is crispy and golden. Flip carefully and cook for another 3–4 minutes. Serve hot with a dipping sauce made of soy sauce, a drop of sesame oil, and a pinch of gochugaru.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/haemul-pajeon-step3.png'),
  ('2798057f-b887-4530-b556-f6b673268c7e', '0d478055-e136-4365-a38c-081688b5a67a', 1, 'Make the marinade', 'In a bowl, mix gochujang (1 tbsp), gochugaru (0.5 tbsp), soy sauce (1 tbsp), sugar (0.5 tbsp), and minced garlic (0.5 tbsp). Add the pork slices and toss well to coat. Let it marinate for 15 minutes.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/jeyuk-bokkeum-step1.png'),
  ('413aacb3-bbc2-4371-9b4c-43b5e11d6188', '0d478055-e136-4365-a38c-081688b5a67a', 2, 'Stir-fry', 'Heat a skillet over high heat. Add the marinated pork and sliced onion. Stir-fry for 5–6 minutes until the pork is cooked through and the edges are slightly crispy/caramelized.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/jeyuk-bokkeum-step2.png'),
  ('0c8e7f91-0cda-4636-9fa9-515245d236f8', '0d478055-e136-4365-a38c-081688b5a67a', 3, 'Season & serve', 'Remove from heat, drizzle with sesame oil (0.5 tsp), and garnish with chopped green onions. Serve with rice and fresh lettuce leaves for wrapping.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/jeyuk-bokkeum-step3.png'),
  ('a5ee32fa-0791-4178-b288-5c39755600b8', 'ccecb95a-c648-45ba-87a2-507b73e6bbcf', 1, 'Make the sauce', 'In a small bowl, mix gochujang (1 tbsp), gochugaru (0.5 tbsp), soy sauce (0.5 tbsp), and minced garlic (1 tsp).', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/ojingeo-bokkeum-step1.png'),
  ('69ec972c-8aa5-4cad-8571-295f9ce2b7e8', 'ccecb95a-c648-45ba-87a2-507b73e6bbcf', 2, 'Stir-fry', 'Heat a skillet over high heat. Add the sliced onion and squid. Stir-fry for 2–3 minutes. Add the sauce mixture and continue to stir-fry for 1–2 minutes until the squid is just cooked and well-coated.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/ojingeo-bokkeum-step2.png'),
  ('5a33736e-704c-46c7-b98f-7cec3de4a436', 'ccecb95a-c648-45ba-87a2-507b73e6bbcf', 3, 'Finish & serve', 'Remove from heat, toss in the green onions, and drizzle with sesame oil. Garnish with sesame seeds and serve immediately.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/ojingeo-bokkeum-step3.png'),
  ('e956379b-5dcd-438d-b30b-930272efec19', '0e82655a-bf7d-4c79-acc7-15afb2b05e82', 1, 'Season the pork', 'Lightly sprinkle both sides of the pork belly slices with salt (0.5 tsp).', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/samgyeopsal-step1.png'),
  ('ef6845d0-648a-410b-b976-384273c11ffd', '29f4d71c-8c56-4bb4-aa39-66bdf59abe02', 1, 'Boil the water', 'Pour 2.5 cups (600ml) of water into a pot and bring it to a rolling boil over high heat (4 mins).', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/kimchi-ramen-step1.png'),
  ('576846c8-1097-4d2d-bbbc-8eb17efa7a57', '0e82655a-bf7d-4c79-acc7-15afb2b05e82', 2, 'Grill the pork', 'Heat a heavy skillet or grill pan over medium-high heat. Arrange the pork slices in a single layer and grill for 3–4 minutes per side, until crispy and golden brown. If using sliced garlic or kimchi, add them to the pan to grill alongside the pork.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/samgyeopsal-step2.png'),
  ('37621abc-db51-44a0-8422-0a40d5f92cbb', '0e82655a-bf7d-4c79-acc7-15afb2b05e82', 3, 'Serve', 'Serve the crispy pork hot. Dip pieces in sesame oil mixed with a pinch of salt. For the full experience, wrap a piece of pork, some kimchi, and a bit of ssamjang in a lettuce leaf.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/samgyeopsal-step3.png'),
  ('fddb28c6-d7eb-4a30-a41d-a33ff3e52268', '4a39c03b-72ba-46e5-9504-baab3b60eb8b', 1, 'Prepare the broth', 'Bring 2 cups (500ml) of anchovy broth to a rolling boil in a pot over medium-high heat (5 mins), adding minced garlic (1 clove) and soy sauce (1 tbsp).', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/anchovy-noodle-soup-step1.png'),
  ('7fbdac2e-4556-42ce-9d73-26ffb714d3b5', '4a39c03b-72ba-46e5-9504-baab3b60eb8b', 2, 'Cook the zucchini', 'Add the julienned zucchini (50g) to the boiling broth and cook for 3 minutes until tender. Reduce heat to low to keep warm.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/anchovy-noodle-soup-step2.png'),
  ('94132e91-ec5e-42a3-8772-d04d792d558b', '4a39c03b-72ba-46e5-9504-baab3b60eb8b', 3, 'Cook the noodles', 'In a separate pot, bring 4 cups of water to a boil over high heat (5 mins). Add the wheat noodles (100g) and cook for 4 minutes, stirring occasionally to prevent sticking.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/anchovy-noodle-soup-step3.png'),
  ('75a7f581-d53e-488e-8553-3e3162d3ae09', '4a39c03b-72ba-46e5-9504-baab3b60eb8b', 4, 'Rinse the noodles', 'Drain the cooked noodles thoroughly in a colander and rinse them under cold running water for 30 seconds to remove excess starch.', NULL),
  ('8591d831-ac11-4844-b830-ba80c4fd1852', '4a39c03b-72ba-46e5-9504-baab3b60eb8b', 5, 'Make egg strips', 'Crack the egg (1) into a small bowl and beat it lightly with a fork. Heat a non-stick skillet over medium heat with a few drops of oil, pour in the egg, cook for 1 minute per side to make a thin omelet, and slice it into thin strips.', NULL),
  ('f631dc4b-1449-41fc-abf5-f353bd6c7f3d', '4a39c03b-72ba-46e5-9504-baab3b60eb8b', 6, 'Assemble & serve', 'Place the rinsed noodles into a serving bowl, pour the hot anchovy broth and zucchini over them, and top with the egg strips, sliced green onions, and a drizzle of sesame oil (0.5 tsp).', NULL),
  ('7735b6e9-5f48-4065-ac81-81685f80d096', 'f8655b9e-1919-415a-971a-4c2651bd633e', 1, 'Make the sauce', 'In a small mixing bowl, combine gochujang (1.5 tbsp), vinegar (1 tbsp), sugar (0.5 tbsp), and sesame oil (0.5 tbsp). Whisk thoroughly until the sugar is completely dissolved, then set the sauce aside.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/bibim-naengmyeon-step1.png'),
  ('d64678cf-6e36-49cb-a72e-63af17e4cecc', 'f8655b9e-1919-415a-971a-4c2651bd633e', 2, 'Cook the noodles', 'Bring a pot of water to a rolling boil over high heat (5 mins). Add the buckwheat noodles (100g) and cook for 3 minutes, stirring continuously to prevent clumping.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/bibim-naengmyeon-step2.png'),
  ('9fcc89ba-7916-47c4-91cd-5c6d365b2937', 'f8655b9e-1919-415a-971a-4c2651bd633e', 3, 'Chill the noodles', 'Drain the noodles immediately and rinse them vigorously under ice-cold running water for 1 minute until completely chilled. Drain thoroughly to remove all excess water.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/bibim-naengmyeon-step3.png'),
  ('3f5d7bd5-cb3e-496c-8bea-85d38adc0dc0', 'f8655b9e-1919-415a-971a-4c2651bd633e', 4, 'Toss with sauce', 'Place the chilled noodles in a serving bowl, pour the prepared gochujang sauce directly over the top, and toss well using chopsticks until every strand is evenly coated.', NULL),
  ('5ca6a4db-feee-48e3-b3aa-b07e6907db37', 'f8655b9e-1919-415a-971a-4c2651bd633e', 5, 'Garnish & serve', 'Garnish the noodles with the halved hard-boiled egg (1) and julienned cucumber (40g). Sprinkle with sesame seeds (0.5 tsp) before serving.', NULL),
  ('b88bc354-017f-4621-8880-41cc32a4a8cf', 'a14a1e4f-d8ee-4ca8-ac15-cb64011152f2', 3, 'Sauté vegetables', 'Heat a skillet over medium heat with 1 tsp of oil. Sauté the sliced carrots (30g), onions (40g), and mushrooms (75g) separately with a pinch of salt and minced garlic for 2 minutes each, setting them aside on a plate.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/japchae-step3.png'),
  ('95203a62-9630-4004-8036-4c7496944c4d', 'a14a1e4f-d8ee-4ca8-ac15-cb64011152f2', 4, 'Cook the beef', 'If using beef (75g), stir-fry it in the same skillet over high heat for 3 minutes until fully cooked, then set aside.', NULL),
  ('aef13056-58df-4d2a-8ea7-9299218d3f47', 'a14a1e4f-d8ee-4ca8-ac15-cb64011152f2', 5, 'Cook noodles in sauce', 'Bring 2 cups of water mixed with soy sauce (1.5 tbsp) and sugar (0.5 tbsp) to a boil in a pan. Add the soaked glass noodles and cook for 3 minutes over medium heat until the liquid is absorbed and the noodles are tender and translucent.', NULL),
  ('7511ae2e-2449-47b5-8969-fc1c24faa331', 'a14a1e4f-d8ee-4ca8-ac15-cb64011152f2', 6, 'Combine & serve', 'Turn off the heat, add the sautéed vegetables, beef, sesame oil (1 tbsp), and mix everything together thoroughly. Garnish with optional egg strips.', NULL),
  ('a6e57e46-f253-4f05-b199-693537493ec9', 'de91c0d1-3663-401e-b9be-e95827a71474', 1, 'Marinate the beef', 'In a small bowl, combine the thinly sliced beef tenderloin (100g) with soy sauce (0.5 tbsp), sugar (0.25 tbsp), and a few drops of sesame oil. Let it marinate for 15 minutes at room temperature.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/japchae-with-beef-step1.png'),
  ('ac640013-3cda-47bc-9bf4-eef4fd70d103', 'de91c0d1-3663-401e-b9be-e95827a71474', 2, 'Soak the noodles', 'Soak the glass noodles (100g) in warm water for 20 minutes, drain, and set aside.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/japchae-with-beef-step2.png'),
  ('527e6055-c65e-4948-b2f6-8ca34fab9fc2', 'de91c0d1-3663-401e-b9be-e95827a71474', 3, 'Blanch the spinach', 'Bring a pot of water to a boil over high heat, blanch the spinach (50g) for 30 seconds, rinse under cold water, and squeeze dry.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/japchae-with-beef-step3.png'),
  ('4a8db17d-3d81-46c0-ba1b-53b914e3c878', 'de91c0d1-3663-401e-b9be-e95827a71474', 4, 'Stir-fry the beef', 'Heat a skillet over medium-high heat with 1 tsp of oil. Stir-fry the marinated beef for 3–4 minutes until fully browned, then remove from the pan.', NULL),
  ('f0b0a683-8559-4d67-b13e-1ec99d0391ac', 'de91c0d1-3663-401e-b9be-e95827a71474', 5, 'Sauté vegetables', 'In the same skillet, briefly sauté the mushrooms (75g) and carrots (30g) for 2 minutes with a pinch of salt.', NULL),
  ('7dfc3fbc-dc44-483a-8d11-8880f9f1ad3f', 'de91c0d1-3663-401e-b9be-e95827a71474', 6, 'Combine & serve', 'Boil the glass noodles in a pot of water for 3 minutes, drain well, and toss with the remaining soy sauce (1 tbsp), sugar, and sesame oil (1 tbsp) in a large bowl. Add the cooked beef, spinach, and vegetables, mixing everything together thoroughly before serving.', NULL),
  ('3484e6d8-72ae-4667-a41d-410edf99d820', 'fc6cbd05-b31a-4ab4-af4d-8dd72b846359', 1, 'Cook the pork', 'Heat a wok or large skillet over medium-high heat with 1 tbsp of oil. Add the diced pork shoulder (100g) and stir-fry for 4 minutes until completely cooked and lightly browned.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/jjajangmyeon-step1.png'),
  ('2d60407b-a218-4e32-90a6-91caa316b26c', 'fc6cbd05-b31a-4ab4-af4d-8dd72b846359', 2, 'Add vegetables', 'Add the diced onions (50g), zucchini (40g), and potatoes (50g) to the wok. Stir-fry together for 4 minutes until the vegetables begin to soften.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/jjajangmyeon-step2.png'),
  ('7b3604be-d455-4150-99ba-c78fbb012060', 'fc6cbd05-b31a-4ab4-af4d-8dd72b846359', 3, 'Fry the black bean paste', 'Push the ingredients to one side of the wok, add the black bean paste (2 tbsp) into the cleared space, and fry the paste in the oil for 2 minutes to remove any bitter flavor, then mix it into the meat and vegetables.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/jjajangmyeon-step3.png'),
  ('3f6b51d0-8e83-446c-849f-7a3c3cbac73a', 'fc6cbd05-b31a-4ab4-af4d-8dd72b846359', 4, 'Simmer the sauce', 'Pour 1 cup (250ml) of water and sugar (0.5 tbsp, if using) into the wok. Bring to a boil over high heat (3 mins), then reduce heat to medium-low, cover, and simmer for 10 minutes until the potatoes are tender and the sauce thickens.', NULL),
  ('d8af42ca-5e2c-4f6c-8301-4fcbff23fec7', 'fc6cbd05-b31a-4ab4-af4d-8dd72b846359', 5, 'Cook the noodles', 'In a separate pot, boil 4 cups of water over high heat, add the wheat noodles (100g), and cook for 5 minutes. Drain thoroughly.', NULL),
  ('58fa4199-2c84-4a76-8e12-3e836aef24c1', 'fc6cbd05-b31a-4ab4-af4d-8dd72b846359', 6, 'Serve', 'Place the cooked noodles in a bowl, ladle the hot black bean sauce generously over the top, and garnish with fresh cucumber strips (30g).', NULL),
  ('8dadfae9-40e8-4359-b19c-5d3e330d9bdf', '69793bb5-a730-454f-94b8-dbf32ad776fd', 1, 'Make chili oil', 'Heat a wok over medium-high heat with 1 tbsp of cooking oil. Add the minced garlic and gochugaru (1.5 tbsp), stir-frying carefully for 30 seconds to create a fragrant chili oil without burning it.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/jjamppong-step1.png'),
  ('7bbc1399-a460-465a-93d7-fbc656f41049', '69793bb5-a730-454f-94b8-dbf32ad776fd', 2, 'Sauté vegetables', 'Add the sliced onions (40g), chopped cabbage (50g), and sliced mushrooms (50g) to the wok. Stir-fry on high heat for 3 minutes until the vegetables start to wilt.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/jjamppong-step2.png'),
  ('d5c698d5-fcd5-47db-ae2e-f4da6694e86c', '69793bb5-a730-454f-94b8-dbf32ad776fd', 3, 'Add the seafood', 'Add the seafood mix (150g) and soy sauce (1 tbsp) to the wok, tossing everything together continuously for 2 minutes.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/jjamppong-step3.png'),
  ('34fdce15-d246-417b-9208-1f3dd2607394', '69793bb5-a730-454f-94b8-dbf32ad776fd', 4, 'Build the broth', 'Pour 2.5 cups (600ml) of water into the wok. Bring the mixture to a rolling boil over high heat (5 mins), then reduce to medium heat and let it simmer for 5 minutes to develop a deep, spicy broth.', NULL),
  ('62262788-6039-406f-af00-8e36a3b5d393', '69793bb5-a730-454f-94b8-dbf32ad776fd', 5, 'Cook the noodles', 'In a separate pot, boil water and cook the wheat noodles (100g) for 4 minutes. Drain and place into a serving bowl.', NULL),
  ('68d57096-654b-4378-b241-59e1ea6b814b', '69793bb5-a730-454f-94b8-dbf32ad776fd', 6, 'Serve', 'Ladle the piping hot spicy seafood soup directly over the noodles, garnish with chopped green onions, and serve immediately.', NULL),
  ('a0c29098-da56-4cb4-9a4a-0f2e4a723e3c', 'c3ab26a9-00c0-4405-a1af-7f9c19386187', 1, 'Season the broth', 'In a pot, combine the anchovy broth (2 cups/500ml), minced garlic (1 clove), and soy sauce (0.5 tbsp). Bring to a boil over medium-high heat (5 mins).', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/kalguksu-step1.png'),
  ('45d5f0ab-18de-4329-95fa-06ec9182b8bf', 'c3ab26a9-00c0-4405-a1af-7f9c19386187', 2, 'Simmer vegetables', 'Add the sliced onions (30g), julienned zucchini (40g), and thin potato slices (30g, if using) to the boiling broth. Reduce heat to medium and simmer for 10 minutes until the vegetables are tender.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/kalguksu-step2.png'),
  ('7e0a2420-3e60-4ce5-a4eb-9142c8817ea5', 'c3ab26a9-00c0-4405-a1af-7f9c19386187', 3, 'Add the noodles', 'Gently shake off any excess flour from the wheat noodles (100g) and add them directly into the simmering broth.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/kalguksu-step3.png'),
  ('b5bccf1d-9f81-4480-984b-4004b937b6fb', 'c3ab26a9-00c0-4405-a1af-7f9c19386187', 4, 'Cook in broth', 'Cook the noodles uncovered for 5 minutes over medium heat, stirring gently with chopsticks to prevent them from sticking to the bottom of the pot.', NULL),
  ('292a51b8-085d-4eb7-9ebf-294635d51794', 'c3ab26a9-00c0-4405-a1af-7f9c19386187', 5, 'Garnish & serve', 'Once the noodles turn soft and translucent, turn off the heat, garnish with chopped green onions, and serve hot in a bowl.', NULL),
  ('9005348e-9cac-4a87-ad1f-0a03c9ea77b9', '29f4d71c-8c56-4bb4-aa39-66bdf59abe02', 2, 'Add noodles & kimchi', 'Add the instant ramen noodles, seasoning packet, and chopped fermented kimchi (0.5 cup) into the boiling water. If using Spam (50g), add it now as well.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/kimchi-ramen-step2.png'),
  ('39ad3202-b1fa-44de-b2e4-4762c856e189', '29f4d71c-8c56-4bb4-aa39-66bdf59abe02', 3, 'Cook the ramen', 'Cook the mixture on medium-high heat for 3 minutes, stirring occasionally to separate the noodles.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/kimchi-ramen-step3.png'),
  ('1e1e4d9c-74dc-466e-b876-02426df86fd2', '29f4d71c-8c56-4bb4-aa39-66bdf59abe02', 4, 'Add the egg', 'Crack the egg (1) directly into the center of the pot without stirring, and let it cook for 2 minutes to achieve a soft-boiled yolk.', NULL),
  ('c092f49a-3def-4751-8c90-7aac55911d12', '29f4d71c-8c56-4bb4-aa39-66bdf59abe02', 5, 'Season & serve', 'Turn off the heat, drizzle with sesame oil (0.5 tsp), top with chopped green onions and a slice of cheese (if using), and serve hot.', NULL),
  ('06849196-80a2-4e9a-a7ba-d65a4fe671ba', '17ef2e58-064b-46d8-847e-f30f98bb47e1', 1, 'Chill the soy milk', 'In a bowl, mix the unsweetened soy milk (1.5 cups/375ml) with salt (0.5 tsp) until dissolved. Place it in the refrigerator to chill thoroughly until ready to use.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/kongguksu-step1.png'),
  ('a7f3544e-4f95-4fe5-9aaf-d2d5ac917138', '17ef2e58-064b-46d8-847e-f30f98bb47e1', 2, 'Cook the noodles', 'Bring a pot of water to a rolling boil over high heat (5 mins). Add the wheat noodles (100g) and cook for 4 minutes, stirring frequently.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/kongguksu-step2.png'),
  ('65eb0fda-b02f-4382-8c9e-db455b493115', '17ef2e58-064b-46d8-847e-f30f98bb47e1', 3, 'Chill the noodles', 'Drain the noodles and rinse them vigorously under cold running water for 1 minute until completely cold. Drain well.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/kongguksu-step3.png'),
  ('12e6f514-8d5d-47b2-9ad4-cd2197ef7293', '17ef2e58-064b-46d8-847e-f30f98bb47e1', 4, 'Assemble', 'Place the cold noodles into a serving bowl, pour the chilled salted soy milk broth directly over the top.', NULL),
  ('c528d51c-b5cd-4281-a518-a3d5cd1a2642', '17ef2e58-064b-46d8-847e-f30f98bb47e1', 5, 'Garnish & serve', 'Garnish the dish with julienned cucumbers (30g), toasted sesame seeds (0.5 tbsp), and tomato wedges (40g, if using) before serving.', NULL),
  ('091fe667-1f11-402a-8aa1-b548941789e3', 'a3d54e4c-47b7-4fda-9b78-368518ffd388', 1, 'Prepare the broth', 'In a bowl, combine the beef broth (2 cups/500ml), vinegar (1 tbsp), sugar (0.5 tbsp), and soy sauce (0.5 tbsp). Stir until the sugar dissolves completely, then place in the freezer for 10 minutes to ice slightly.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/mul-naengmyeon-step1.png'),
  ('fb6b9d1a-cff2-4ca1-a844-2f84ef132f88', 'a3d54e4c-47b7-4fda-9b78-368518ffd388', 2, 'Cook the noodles', 'Bring a pot of water to a boil over high heat (5 mins). Add the buckwheat noodles (100g) and cook for 3 minutes, stirring constantly.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/mul-naengmyeon-step2.png'),
  ('9cd1e16d-43f2-4669-9bfc-45cda094b09d', 'a3d54e4c-47b7-4fda-9b78-368518ffd388', 3, 'Chill the noodles', 'Drain the noodles and rinse them thoroughly under ice-cold running water for 1 minute to remove starch and chill them completely.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/mul-naengmyeon-step3.png'),
  ('ca016ba4-38e3-40c6-bdcd-0d631043ab2b', 'a3d54e4c-47b7-4fda-9b78-368518ffd388', 4, 'Assemble the bowl', 'Place the noodles in a serving bowl and pour the ice-cold seasoned beef broth over them.', NULL),
  ('ced3159b-a5a6-458c-9eb9-7ea399879554', 'a3d54e4c-47b7-4fda-9b78-368518ffd388', 5, 'Add toppings', 'Top with the halved hard-boiled egg (1), pickled radish (25g), julienned cucumber (30g), and a dab of mustard paste (0.5 tsp, if using) on the side.', NULL),
  ('15101def-f293-4b45-bba4-7553db3f4e5c', '73524265-8c6c-4046-b5ef-a6880da25607', 1, 'Prep the squid', 'Clean the squid (150g) and slice it cleanly into thin rings or bite-sized pieces.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/ojingeo-bokkeum-noodles-step1.png')
INSERT INTO pantry_recipe_steps ("id", "recipe_id", "step_order", "title", "description", "image_url") VALUES
  ('2f698ef0-b5c1-4496-a317-1ccb34fc208a', '73524265-8c6c-4046-b5ef-a6880da25607', 2, 'Make the sauce', 'In a small bowl, mix together gochujang (1 tbsp), gochugaru (0.5 tbsp), soy sauce (0.5 tbsp), and minced garlic (1 clove) to form a paste.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/ojingeo-bokkeum-noodles-step2.png'),
  ('0ddfee34-2877-4934-8fa8-9300894cf3c9', '73524265-8c6c-4046-b5ef-a6880da25607', 3, 'Stir-fry squid', 'Heat a skillet over high heat with 1 tbsp of oil. Add the sliced onions (30g) and squid rings, stir-frying for 2 minutes.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/ojingeo-bokkeum-noodles-step3.png'),
  ('e498b3fb-c1a0-4309-b827-44d147ce3883', '73524265-8c6c-4046-b5ef-a6880da25607', 4, 'Add sauce', 'Add the sauce mixture to the skillet and stir-fry everything together for another 2 minutes until the squid is opaque and completely coated in the spicy sauce.', NULL),
  ('2c862c85-cc7b-49d0-81d9-0a13c831ec1a', '73524265-8c6c-4046-b5ef-a6880da25607', 5, 'Cook the noodles', 'In a separate pot, boil water and cook the wheat noodles (100g) for 4 minutes. Drain thoroughly.', NULL),
  ('a36d2ecd-a436-4b58-881a-63292519a591', '73524265-8c6c-4046-b5ef-a6880da25607', 6, 'Toss & serve', 'Add the cooked noodles directly into the skillet with the spicy squid, drizzle with sesame oil (0.5 tsp), toss well on low heat for 1 minute, garnish with green onions, and serve.', NULL),
  ('71c08f17-b0c6-4482-9852-e3b36249fccb', '240a0ec9-e027-4b6f-a836-751d13831424', 1, 'Boil the water', 'Pour 2.5 cups (600ml) of water into a pot and bring to a rolling boil over high heat (4 mins).', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/ramyeon-upgrade-step1.png'),
  ('b0c5ac29-87b4-4ab2-952d-dc616dae9307', '240a0ec9-e027-4b6f-a836-751d13831424', 2, 'Add all ingredients', 'Add the ramen noodles, seasoning packet, chopped kimchi (0.5 cup), sliced mushrooms (30g, if using), and Spam cubes (50g, if using) into the boiling water.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/ramyeon-upgrade-step2.png'),
  ('1780a5d7-d50e-4675-b08b-a01e25be27ad', '240a0ec9-e027-4b6f-a836-751d13831424', 3, 'Cook the ramen', 'Cook the mixture over medium-high heat for 3 minutes, stirring to loosen the noodles.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/ramyeon-upgrade-step3.png'),
  ('0ea58368-b962-4cd1-bb75-96f3e69ceb94', '240a0ec9-e027-4b6f-a836-751d13831424', 4, 'Add the egg', 'Crack the egg (1) directly into the bubbling broth without breaking the yolk, and cook for 2 minutes.', NULL),
  ('6fd1d1ba-0b7e-4e5c-b4df-e18df9167f21', '240a0ec9-e027-4b6f-a836-751d13831424', 5, 'Season & serve', 'Remove from heat, drizzle with sesame oil (0.5 tsp), garnish with fresh chopped green onions, and serve immediately.', NULL),
  ('f31ca9cf-e243-4274-8d80-b2cce11a05c5', '02b3c162-40b8-4a69-889a-851e8f212f95', 1, 'Prep the rice cakes', 'If the rice cakes (150g) are frozen, soak them in warm water for 10 minutes to soften, then drain.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/tteok-ramen-step1.png'),
  ('2cb0422e-60fa-471c-a4f8-170072f3e0dd', '02b3c162-40b8-4a69-889a-851e8f212f95', 2, 'Boil the water', 'Pour 2.5 cups (600ml) of water into a pot and bring to a rolling boil over high heat (4 mins).', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/tteok-ramen-step2.png'),
  ('172c3f1b-d81f-4cde-8219-ffdc34e9da02', '02b3c162-40b8-4a69-889a-851e8f212f95', 3, 'Cook noodles & rice cakes', 'Add the instant ramen noodles, seasoning packet, and softened rice cakes into the boiling water. Cook on medium-high heat for 3 minutes.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/tteok-ramen-step3.png'),
  ('af204ac1-34c4-4cb1-a68e-d2e4168dfdb0', '02b3c162-40b8-4a69-889a-851e8f212f95', 4, 'Add the egg', 'Crack the egg (1) gently into the pot and let it cook for 2 minutes undisturbed.', NULL),
  ('ad735a3e-9d1a-40d9-b0a9-f01a511e3174', '02b3c162-40b8-4a69-889a-851e8f212f95', 5, 'Serve', 'Turn off the heat, top with a slice of cheese (if using), Spam slices (if using), and chopped green onions. Serve hot.', NULL),
  ('11e6d060-7a61-481f-b494-414822260d6d', 'b1fafe32-dc17-4200-97fd-dde5dbd9f369', 1, 'Blanch vegetables', 'Blanch the spinach (50g) and bean sprouts (50g) separately in boiling water for 30 seconds, rinse under cold water, and drain completely.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/bibimbap-step1.png'),
  ('4870eda5-e6fc-4e25-8611-af3fd32cde67', 'b1fafe32-dc17-4200-97fd-dde5dbd9f369', 2, 'Sauté carrots & mushrooms', 'Sauté the sliced carrots (25g) and mushrooms (50g) separately in a pan with a drop of oil, soy sauce, and sesame oil over medium-high heat for 2 minutes.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/bibimbap-step2.png'),
  ('cb219cd4-1f5d-4133-a2cf-0561521a7746', 'b1fafe32-dc17-4200-97fd-dde5dbd9f369', 3, 'Cook the beef', 'If using beef (75g), stir-fry it in a skillet over high heat for 3 minutes until fully cooked.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/bibimbap-step3.png'),
  ('a6b91661-f41a-4638-8758-260f2a971f3f', 'b1fafe32-dc17-4200-97fd-dde5dbd9f369', 4, 'Fry the egg', 'Fry an egg sunny-side up in a pan over medium heat for 2 minutes.', NULL),
  ('6fcc81e4-c5e8-4e03-9cf7-6f7c062c4b69', 'b1fafe32-dc17-4200-97fd-dde5dbd9f369', 5, 'Assemble the bowl', 'Place the warm rice (1 cup/150g) in a serving bowl, arrange each prepared vegetable and beef neatly in separate sections on top, and place the fried egg in the center.', NULL),
  ('29d86709-77b9-4166-adba-63938c490d59', 'b1fafe32-dc17-4200-97fd-dde5dbd9f369', 6, 'Mix & serve', 'Add gochujang (1 tbsp) and sesame oil (0.5 tbsp), then mix everything together vigorously before eating.', NULL),
  ('f2f41fc3-605c-41af-ad03-71190ca4fd70', 'd0755f5d-0b2c-4f96-a20a-a07d9f91e8e4', 1, 'Sauté everything', 'Heat a pot over medium-high heat with 1 tsp of oil. Sauté the diced onion (50g), potato (70g), carrot (35g), minced garlic (3g), and chicken (100g) for 4 minutes until lightly browned.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/curry-rice-step1.png'),
  ('e48039df-c841-4d8d-9fa8-fc40dc91589f', 'd0755f5d-0b2c-4f96-a20a-a07d9f91e8e4', 2, 'Add water & simmer', 'Pour 1 cup (250ml) of water into the pot, bring to a boil over high heat (4 mins), then reduce heat to medium-low, cover, and simmer for 15 minutes until vegetables are soft.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/curry-rice-step2.png'),
  ('f94a774b-9c5f-4bda-8b67-3a60293a5cac', 'd0755f5d-0b2c-4f96-a20a-a07d9f91e8e4', 3, 'Add curry powder', 'Reduce heat to low, add the curry powder (1 tbsp), and stir continuously until completely dissolved and smooth.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/curry-rice-step3.png'),
  ('48ab2870-44d0-4b78-b823-a5c5fa47608f', 'd0755f5d-0b2c-4f96-a20a-a07d9f91e8e4', 4, 'Thicken the curry', 'Simmer the curry uncovered for 10 more minutes over low heat until thick and glossy.', NULL),
  ('92116917-bad5-4cb5-84dc-acb91bdd18ca', 'd0755f5d-0b2c-4f96-a20a-a07d9f91e8e4', 5, 'Serve over rice', 'Ladle the hot curry generously over a plate of cooked rice (1 cup/150g) and serve.', NULL),
  ('95160e92-8e44-4d95-8717-86f13a06a54d', '8133387a-d80b-4737-9bb1-5714951a8280', 1, 'Cook the chicken', 'Heat a skillet over medium-high heat with 1 tsp of oil. Stir-fry the chicken thigh pieces (100g) with gochujang (1 tbsp), soy sauce (0.5 tbsp), and minced garlic (1 clove) for 5 minutes until fully cooked.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/dakgalbi-bokkeumbap-step1.png'),
  ('8f835997-c016-4cf8-a9ae-78954def4e2b', '8133387a-d80b-4737-9bb1-5714951a8280', 2, 'Stir-fry with rice', 'Add the cooked rice (1 cup/150g) directly into the skillet and stir-fry everything together vigorously for 3 minutes until evenly coated and heated through.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/dakgalbi-bokkeumbap-step2.png'),
  ('f8880f67-96c7-4073-80d7-d4b34397023f', '8133387a-d80b-4737-9bb1-5714951a8280', 3, 'Season', 'Drizzle with sesame oil (0.5 tsp) and top with chopped green onions (15g).', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/dakgalbi-bokkeumbap-step3.png'),
  ('18ac50e2-04e8-4fef-8331-0316c394cfac', '8133387a-d80b-4737-9bb1-5714951a8280', 4, 'Add cheese & serve', 'If using cheese (1 slice/15g), place it on top, cover the pan for 1 minute on low heat until melted, and serve.', NULL),
  ('596a5e06-0345-4746-9ca5-b784beeaef33', '304b3c71-0b3f-412c-baf8-16b943d09b38', 1, 'Sauté zucchini', 'Sauté the sliced zucchini (40g) in a pan with a pinch of salt over medium heat for 2 minutes until tender.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/doenjang-bibimbap-step1.png'),
  ('6183bbd4-3648-4ff1-9306-77f64b497b72', '304b3c71-0b3f-412c-baf8-16b943d09b38', 2, 'Blanch sprouts & spinach', 'Blanch the bean sprouts (50g) and spinach (50g) separately in boiling water for 30 seconds, rinse with cold water, and squeeze dry.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/doenjang-bibimbap-step2.png'),
  ('0bf13af8-f511-4252-8995-d99f8621bc0c', '304b3c71-0b3f-412c-baf8-16b943d09b38', 3, 'Fry the egg', 'Fry an egg sunny-side up in a skillet with a drop of oil over medium heat for 2 minutes.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/doenjang-bibimbap-step3.png'),
  ('9dbb35ab-b402-4d72-9884-81293c372d1d', '304b3c71-0b3f-412c-baf8-16b943d09b38', 4, 'Make the sauce', 'In a small bowl, mix the doenjang (1 tbsp) with the sesame oil (0.5 tbsp) and minced garlic (2.5g, if using) to create the sauce.', NULL),
  ('fb5c4ada-c05e-4e2c-aa2a-68738d307f04', '304b3c71-0b3f-412c-baf8-16b943d09b38', 5, 'Assemble & serve', 'Place the cooked rice (1 cup/150g) in a serving bowl, arrange the prepared zucchini, bean sprouts, and spinach around the edges, place the fried egg on top, and serve with the doenjang mixture on the side to mix in.', NULL),
  ('621e664d-970f-4ea2-a9ea-fbe53a8ba3fc', '84489729-5d01-4c30-88be-4240557098b7', 1, 'Fry the egg', 'Heat a non-stick skillet over medium heat with 1 tsp of oil and fry an egg to your preferred doneness (sunny-side up recommended for a runny yolk).', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/egg-rice-bowl-step1.png'),
  ('33d2742c-9d82-45b7-9501-e13249df4be5', '84489729-5d01-4c30-88be-4240557098b7', 2, 'Place egg on rice', 'Place the hot cooked rice (1 cup/150g) in a serving bowl and lay the fried egg directly on top.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/egg-rice-bowl-step2.png'),
  ('4ac9869f-7860-4b51-b422-4d4f406ed6b5', '84489729-5d01-4c30-88be-4240557098b7', 3, 'Add seasoning', 'Drizzle soy sauce (1 tbsp) and sesame oil (1 tsp) over the egg and rice.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/egg-rice-bowl-step3.png'),
  ('46674eef-b655-4314-9c1f-f396648069ec', '84489729-5d01-4c30-88be-4240557098b7', 4, 'Garnish & serve', 'Garnish with sesame seeds (0.5 tsp) and chopped green onions (15g, if using), then mix everything together thoroughly before eating.', NULL),
  ('7d358aec-f07f-44d1-b360-30a7ad3fe6b4', '8864f9c2-7932-41c3-b0de-5666e0831271', 1, 'Make egg strips', 'Whisk the eggs (1.5), pour into a skillet heated to 170°C with oil, cook for 2 minutes per side, and cut into long strips.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/gimbap-step1.png'),
  ('15201f1f-489e-4a71-afe8-c8f0e79769cf', '8864f9c2-7932-41c3-b0de-5666e0831271', 2, 'Blanch the spinach', 'Blanch the spinach (50g) in boiling water for 30 seconds, rinse with cold water, squeeze out moisture, and season with a pinch of salt.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/gimbap-step2.png'),
  ('65fa8d4b-e9d5-4518-b885-be225bc63f48', '8864f9c2-7932-41c3-b0de-5666e0831271', 3, 'Sauté the carrots', 'Sauté the julienned carrots (40g) in a pan with oil and a pinch of salt over medium heat for 2 minutes.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/gimbap-step3.png'),
  ('0f20af53-6901-4748-8efc-2855e1e33915', '8864f9c2-7932-41c3-b0de-5666e0831271', 4, 'Season the rice', 'Mix the warm cooked rice (1 cup/150g) thoroughly with salt (0.5 tsp) and half of the sesame oil (0.5 tbsp).', NULL),
  ('c2a30f00-a6b9-4ffb-92cb-04e6ca603e52', '8864f9c2-7932-41c3-b0de-5666e0831271', 5, 'Set up the roll', 'Place a seaweed sheet shiny side down on a bamboo mat, spread an even layer of rice over it, and arrange the egg strips, spinach, carrots, crab sticks, and pickled radish on top.', NULL),
  ('606a1703-c1dd-43e3-977c-00821e45b84a', '17a20784-8931-45eb-bb84-9c54a11db554', 1, 'Marinate the pork', 'In a bowl, combine the thinly sliced pork (150g) with gochujang (1 tbsp), soy sauce (0.5 tbsp), minced garlic (7.5g), sesame oil (0.5 tsp), and gochugaru (3g, if using). Marinate for 15 minutes.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/jeyuk-dupbap-step1.png'),
  ('1c351d1f-ee0f-40f3-862d-125e4692048c', '17a20784-8931-45eb-bb84-9c54a11db554', 2, 'Stir-fry', 'Heat a skillet over high heat. Add the marinated pork and sliced onions (40g), and stir-fry for 5 minutes until the pork is completely cooked through and the edges are slightly caramelized.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/jeyuk-dupbap-step2.png'),
  ('59734a0b-fffa-49ee-bd42-fdf0ac8fbf65', '17a20784-8931-45eb-bb84-9c54a11db554', 3, 'Serve over rice', 'Serve the spicy stir-fried pork hot directly over a bowl of cooked rice (1 cup/150g).', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/jeyuk-dupbap-step3.png'),
  ('5cb7e7b7-b6e9-4118-84a1-c58040e3e241', '17a20784-8931-45eb-bb84-9c54a11db554', 4, 'Garnish', 'Garnish with chopped green onions (15g) before eating.', NULL),
  ('bf1cae9e-7e4e-488c-9881-2b1654d44caa', 'd893e92a-c257-444a-9bb9-941d60a22b3e', 1, 'Crisp the pork belly', 'Heat a skillet over medium-high heat and stir-fry the sliced pork belly (75g) for 4 minutes until crispy and rendered.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/kimchi-bokkeumbap-deluxe-step1.png'),
  ('f2bab497-e455-41d1-9b88-3eb84264ba55', 'd893e92a-c257-444a-9bb9-941d60a22b3e', 2, 'Add kimchi', 'Add the chopped kimchi (80g) and soy sauce (0.5 tbsp) to the skillet, stir-frying together for 3 minutes until the kimchi softens.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/kimchi-bokkeumbap-deluxe-step2.png'),
  ('1a9e31be-9871-46e7-a2c9-c0b09af83271', 'd893e92a-c257-444a-9bb9-941d60a22b3e', 3, 'Stir-fry with rice', 'Add the cooked rice (1 cup/150g) into the skillet and stir-fry everything vigorously on high heat for 4 minutes until well combined and slightly crisp.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/kimchi-bokkeumbap-deluxe-step3.png'),
  ('0690f8ad-769c-466e-9e25-b8e56199bb45', 'd893e92a-c257-444a-9bb9-941d60a22b3e', 4, 'Fry the egg', 'In a separate pan, fry an egg sunny-side up over medium heat for 2 minutes.', NULL),
  ('2fcb7763-ba90-4c6a-b1f5-cb73870e396d', 'd893e92a-c257-444a-9bb9-941d60a22b3e', 5, 'Top & serve', 'Top the fried rice with the fried egg, sesame oil (0.5 tsp), chopped green onions (15g), and a slice of cheese (15g, if using) to melt from the residual heat before serving.', NULL),
  ('baf3d1ee-5baa-44e8-9288-5083825e7baf', '571bf3ed-3ac4-45f3-a9a3-9b6af166001e', 1, 'Chop the kimchi', 'Chop the fermented kimchi (80g) into small, bite-sized pieces.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/kimchi-fried-rice-step1.png'),
  ('83c1e0ae-334f-478f-acf4-ac0105e0406b', '571bf3ed-3ac4-45f3-a9a3-9b6af166001e', 2, 'Stir-fry kimchi', 'Heat 1 tbsp of oil in a pan over high heat, add the chopped kimchi, and stir-fry for 2 minutes.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/kimchi-fried-rice-step2.png'),
  ('b59cd97e-1666-49b3-a653-993a640f3419', '571bf3ed-3ac4-45f3-a9a3-9b6af166001e', 3, 'Add rice', 'Add the cooked rice (1 cup/150g) and soy sauce (0.5 tbsp) to the pan, and stir-fry continuously for 3 to 4 minutes until the rice is evenly colored and slightly crispy.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/kimchi-fried-rice-step3.png'),
  ('23a5539f-a021-408f-a21d-84fa31a51037', '571bf3ed-3ac4-45f3-a9a3-9b6af166001e', 4, 'Fry the egg', 'In a separate pan, fry an egg sunny-side up over medium heat for 2 minutes.', NULL),
  ('0aad99ed-0ece-45c8-9d97-00bdc194d66a', '571bf3ed-3ac4-45f3-a9a3-9b6af166001e', 5, 'Garnish & serve', 'Top the kimchi fried rice with the fried egg, drizzle with sesame oil (0.5 tsp), and garnish with chopped green onions (15g) and sesame seeds (if using).', NULL),
  ('ef0bab7f-eeb5-43dc-bfdb-630ffe29abd3', '916a5de4-87d8-4e77-a824-ca0b94b0e602', 1, 'Season bean sprouts', 'Blanch the bean sprouts (100g) in boiling water for 3 minutes, drain thoroughly, and toss in a bowl with soy sauce (0.5 tbsp), sesame oil (0.5 tbsp), and minced garlic (2.5g).', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/kongnamul-bibimbap-step1.png'),
  ('c838f4e3-7a19-49e4-a8dc-aa968fdff7e9', '916a5de4-87d8-4e77-a824-ca0b94b0e602', 2, 'Fry the egg', 'In a separate skillet heated to 170°C with a drop of oil, fry an egg sunny-side up for 2 minutes.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/kongnamul-bibimbap-step2.png'),
  ('0bf2b207-f4ae-4db6-af25-c1fb32a1b8d4', '916a5de4-87d8-4e77-a824-ca0b94b0e602', 3, 'Place the rice', 'Place the warm cooked rice (1 cup/150g) in a serving bowl.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/kongnamul-bibimbap-step3.png'),
  ('027ce0c6-6217-4ac9-94c7-357ed2fd06e9', '916a5de4-87d8-4e77-a824-ca0b94b0e602', 4, 'Assemble', 'Top the rice with the seasoned bean sprouts and the fried egg, and add a dollop of gochujang (1 tbsp) on the side.', NULL),
  ('3466c797-f0ea-407d-8e6e-f19c1572ca19', '916a5de4-87d8-4e77-a824-ca0b94b0e602', 5, 'Mix & serve', 'Sprinkle with sesame seeds (if using) and mix everything together thoroughly before eating.', NULL),
  ('b91430a8-4b41-4dd5-ab8c-72e5e108d974', 'a90ea148-11be-45a3-8933-4b9f47e1d250', 1, 'Cook chicken & veg', 'Heat 1 tsp of oil in a pan over medium-high heat, add the diced chicken (75g), onion (40g), and carrot (20g), and stir-fry for 4 minutes until cooked.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/omurice-step1.png'),
  ('13927760-d53b-48c7-a25a-0d08f641ca5d', 'a90ea148-11be-45a3-8933-4b9f47e1d250', 2, 'Make ketchup rice', 'Add the cooked rice (1 cup/150g) and ketchup (1.5 tbsp) to the pan, stirring well for 2 minutes until fully incorporated, then remove the fried rice to a plate.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/omurice-step2.png'),
  ('85b3a60b-b6d6-46a4-8282-fa640dc61378', 'a90ea148-11be-45a3-8933-4b9f47e1d250', 3, 'Wrap in omelette', 'In a bowl, beat the eggs (2) thoroughly. Pour into a non-stick pan heated to 170°C with 1 tsp of oil, cook until the edges are just set, place the ketchup fried rice in the center, and carefully fold the omelette over the rice.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/omurice-step3.png'),
  ('95e868c9-e0c3-400b-8b44-2b0dfe29eaf1', 'a90ea148-11be-45a3-8933-4b9f47e1d250', 4, 'Plate & garnish', 'Slide the omurice onto a serving plate, drizzle extra ketchup on top, and garnish with chopped green onions (7.5g, if using).', NULL),
  ('93028760-86d0-46ca-a5f5-58e8690fc576', '1f37b2d8-cbce-43e7-9bc1-5434fd98823e', 1, 'Sauté vegetables', 'Heat a skillet over medium-high heat with 1 tsp of oil. Sauté the sliced zucchini (40g) and mushrooms (50g) with a pinch of salt for 3 minutes until tender, then remove.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/ssamjang-veggie-bowl-step1.png'),
  ('3f77ab07-b3e4-4184-90db-91d42100c001', '1f37b2d8-cbce-43e7-9bc1-5434fd98823e', 2, 'Blanch the spinach', 'Blanch the spinach (50g) in boiling water for 30 seconds, rinse with cold water, squeeze dry, and toss with sesame oil (0.5 tsp).', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/ssamjang-veggie-bowl-step2.png'),
  ('e0fb424d-0366-401e-b91d-a473167ac659', '1f37b2d8-cbce-43e7-9bc1-5434fd98823e', 3, 'Fry the egg', 'If using an egg (1), fry it sunny-side up in a pan over medium heat for 2 minutes.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/ssamjang-veggie-bowl-step3.png'),
  ('7c011b37-8cf7-4679-9155-8eafb9281c4a', '1f37b2d8-cbce-43e7-9bc1-5434fd98823e', 4, 'Assemble', 'Place the cooked rice (1 cup/150g) in a serving bowl, and arrange the sautéed zucchini, mushrooms, and spinach neatly on top.', NULL),
  ('b97a7fe5-abb1-4c1a-a910-df6db349ed2a', '1f37b2d8-cbce-43e7-9bc1-5434fd98823e', 5, 'Serve with ssamjang', 'Serve with ssamjang (1 tbsp) on the side for mixing, topped with the fried egg if desired.', NULL),
  ('c15b2a86-c078-494e-a3b5-28cb77d86a5a', '02ddf148-dcf1-41cc-9c51-cab4bb0b04d9', 2, 'Season', 'In a mixing bowl, toss the sprouts with soy sauce (7.5ml), sesame oil (2.5ml), minced garlic (2.5g), and salt (0.75g).', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/sukju-namul-step2.png'),
  ('f009712f-630d-4e53-9bb3-9d1985464bd0', '2a0ab214-60cf-4d6b-8086-c4d5dc23ea8b', 1, 'Make chili base', 'Heat 1 tsp of oil in a small pot over medium heat. Sauté the minced garlic (1 clove) and gochugaru (1 tbsp) for 30 seconds to release flavors without burning.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/sundubu-dupbap-step1.png'),
  ('d188f73d-73b5-4784-8be7-f32919117a88', '2a0ab214-60cf-4d6b-8086-c4d5dc23ea8b', 2, 'Build the broth', 'Pour 0.5 cup (125ml) of water and soy sauce (0.5 tbsp) into the pot and bring to a boil over high heat (3 mins).', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/sundubu-dupbap-step2.png'),
  ('61f3e63c-ab8e-4370-a1ee-7c454488af15', '2a0ab214-60cf-4d6b-8086-c4d5dc23ea8b', 3, 'Add the tofu', 'Gently add the soft tofu (150g) into the bubbling broth, breaking it up slightly with a spoon. Simmer for 5 minutes.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/sundubu-dupbap-step3.png'),
  ('3c15a046-95d1-44e4-b5c8-a1502770c19d', '2a0ab214-60cf-4d6b-8086-c4d5dc23ea8b', 4, 'Cook the egg', 'Crack the egg (1) directly into the broth, cover the pot, and cook for 1 minute until the egg white is set.', NULL),
  ('3b0d8786-8f8a-424a-9253-71d5b8f7223b', '2a0ab214-60cf-4d6b-8086-c4d5dc23ea8b', 5, 'Serve over rice', 'Remove from heat, drizzle with sesame oil (0.5 tsp, if using), garnish with chopped green onions (7.5g), and serve hot over a bowl of cooked rice (1 cup/150g).', NULL),
  ('180fb101-b345-4454-b084-59d06c3075a2', 'b9816c6c-78a9-420e-bfaf-092a890c6020', 1, 'Drain the tuna', 'Drain the canned tuna thoroughly and place it into a small mixing bowl.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/tuna-mayo-rice-bowl-step1.png'),
  ('48a1fcff-26c1-4b5a-88c6-294b8ecf25e6', 'b9816c6c-78a9-420e-bfaf-092a890c6020', 2, 'Mix tuna mayo', 'Add mayonnaise (2 tbsp), soy sauce (1 tsp), and sesame oil (1 tsp) to the tuna, mixing well until thoroughly combined and creamy.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/tuna-mayo-rice-bowl-step2.png'),
  ('e28a1e23-4064-490e-8251-05f6d63159f6', 'b9816c6c-78a9-420e-bfaf-092a890c6020', 3, 'Prepare the bowl', 'Place the hot cooked rice (1 cup/150g) in a serving bowl.', NULL),
  ('46849a0c-b19a-4c8b-b76d-245e7cea9d96', 'b9816c6c-78a9-420e-bfaf-092a890c6020', 4, 'Top with tuna', 'Scoop the creamy tuna mixture directly onto the center of the rice.', NULL),
  ('9e5e6e57-01ce-4d90-a230-e620973877ef', 'b9816c6c-78a9-420e-bfaf-092a890c6020', 5, 'Garnish & serve', 'Garnish with chopped green onions (15g), sesame seeds (if using), and a pinch of gochugaru (if using) before serving.', NULL),
  ('f6cd98d1-c606-43a2-b093-efa876cd30cc', 'aacf6938-a944-41a7-a6d5-13add8f9d4c4', 1, 'Prep the root', 'Rinse the bellflower root (67g) thoroughly in cold water, squeeze firmly to remove bitterness, and shred into thin strips.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/doraji-namul-step1.png'),
  ('70f64b0a-0374-49d5-9ae8-53d92875d3b6', 'aacf6938-a944-41a7-a6d5-13add8f9d4c4', 2, 'Sauté', 'Heat a pan over medium heat with sesame oil (0.33 tsp) and minced garlic (1.5g), add the bellflower root, and sauté for 3 minutes until softened.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/doraji-namul-step2.png'),
  ('72d8ed32-0472-4ac3-ab46-a66ff46e544f', 'aacf6938-a944-41a7-a6d5-13add8f9d4c4', 3, 'Season', 'Season with salt (1g) and soy sauce (1.6ml), tossing continuously for 1 minute.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/doraji-namul-step3.png'),
  ('e7524bbb-8f8a-499b-81bb-692f518aa9fa', 'aacf6938-a944-41a7-a6d5-13add8f9d4c4', 4, 'Garnish & serve', 'Garnish with sesame seeds and gochugaru (if using) before serving.', NULL),
  ('623a730e-cbb2-42c5-984f-65cb698d3a82', '21d11746-9df4-4dd0-b4ef-fee0b60d9488', 1, 'Prep the tofu', 'Slice the firm tofu (150g) into 1cm slabs and pat completely dry with paper towels.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/dubu-buchim-step1.png'),
  ('1b546eed-7bf1-4c89-aec4-4f667daae014', '21d11746-9df4-4dd0-b4ef-fee0b60d9488', 2, 'Pan-fry the tofu', 'Lightly sprinkle salt (0.75g) over the tofu slices. Heat a pan over medium-high heat with 1 tsp of oil and pan-fry the tofu for 3–4 minutes per side until golden brown on both sides.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/dubu-buchim-step2.png'),
  ('e8a64c59-3f6e-486b-855c-762b91abc128', '21d11746-9df4-4dd0-b4ef-fee0b60d9488', 3, 'Make dipping sauce', 'In a small bowl, mix soy sauce (1 tbsp), sesame oil (2.5ml), gochugaru (1g), and chopped green onion (7.5g) to create the dipping sauce.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/dubu-buchim-step3.png'),
  ('95d35baf-8d32-4691-b59d-7f5eee599d8c', '21d11746-9df4-4dd0-b4ef-fee0b60d9488', 4, 'Serve', 'Serve the pan-fried tofu hot with the dipping sauce on the side.', NULL),
  ('db76b8e7-db48-4699-8cdd-550ce8972834', 'bea57cf9-1711-48de-8ce8-0548a59d2a71', 1, 'Pan-fry the tofu', 'Slice the firm tofu (150g) into slabs, pat dry, and pan-fry in a pan with 1 tsp of oil over medium-high heat for 3 minutes per side until golden.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/dubu-jorim-step1.png'),
  ('5bd900a0-2d02-4efa-874d-cf9c69de125b', 'bea57cf9-1711-48de-8ce8-0548a59d2a71', 2, 'Make the sauce', 'In a small bowl, mix soy sauce (1 tbsp), gochugaru (3g), minced garlic (5g), sesame oil (2.5ml), and 1.5 tbsp (22.5ml) of water.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/dubu-jorim-step2.png'),
  ('c56e96bb-3652-4a97-a76b-ba3d56665a91', 'bea57cf9-1711-48de-8ce8-0548a59d2a71', 3, 'Braise', 'Pour the sauce mixture over the pan-fried tofu. Simmer on medium heat for 5 minutes until the sauce is fully absorbed.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/dubu-jorim-step3.png'),
  ('9bb90cb5-6b7c-4392-8587-d47c98083566', 'bea57cf9-1711-48de-8ce8-0548a59d2a71', 4, 'Garnish & serve', 'Garnish with chopped green onions (15g) and sesame seeds (1g, if using) before serving.', NULL),
  ('db0406be-2107-4a66-a11f-18ce77b59038', '40240fe6-bcde-4797-aef1-ea7392dfb21c', 1, 'Slice the fish cake', 'Slice the fish cake (100g) into bite-sized strips or squares.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/eomuk-bokkeum-step1.png'),
  ('fc8ec2f8-f312-4e27-b34e-ebb5ae630533', '40240fe6-bcde-4797-aef1-ea7392dfb21c', 2, 'Stir-fry', 'Heat a pan over medium-high heat with 1 tsp of oil, add minced garlic (1.5g), and stir-fry the fish cake with soy sauce (10ml) and sugar (1.3g) for 3–4 minutes.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/eomuk-bokkeum-step2.png'),
  ('08b61185-d7e1-4d4f-89b5-ae2caec5030e', '40240fe6-bcde-4797-aef1-ea7392dfb21c', 3, 'Finish with sesame', 'Turn off the heat, stir in the chopped green onions (10g) and sesame oil (1.6ml).', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/eomuk-bokkeum-step3.png'),
  ('516f2ad4-e1b2-4999-a760-9a7dde6a3bbf', '40240fe6-bcde-4797-aef1-ea7392dfb21c', 4, 'Garnish & serve', 'Garnish with sesame seeds and gochugaru (if using) before serving.', NULL),
  ('449413a7-79bd-497d-b08a-9e3e38c07972', '0aa91e03-3125-4bd7-a818-d4e347bd2570', 1, 'Cook the eggplant', 'Steam or microwave the eggplant (150g) for 4 minutes until completely soft. Let it cool slightly, then tear into long strips by hand.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/gaji-namul-step1.png')
INSERT INTO pantry_recipe_steps ("id", "recipe_id", "step_order", "title", "description", "image_url") VALUES
  ('4f9dfae8-e4e5-4052-9012-3f771211e9c4', '0aa91e03-3125-4bd7-a818-d4e347bd2570', 2, 'Season', 'In a mixing bowl, combine the eggplant strips with soy sauce (7.5ml), sesame oil (2.5ml), minced garlic (2.5g), and gochugaru (1g, if using).', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/gaji-namul-step2.png'),
  ('cfab4fd2-4103-4191-a935-c18e8a273073', '0aa91e03-3125-4bd7-a818-d4e347bd2570', 3, 'Garnish & serve', 'Toss gently to combine, garnish with chopped green onions (7.5g) and sesame seeds (1g, if using), and serve.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/gaji-namul-step3.png'),
  ('6821248b-d835-4d02-bf5f-c273cd0ff40f', '5c8b95ab-6c0b-40d1-a631-9f2bff8c443c', 1, 'Prep the potatoes', 'Cut the potato (130g) into bite-sized cubes and rinse them in cold water for 1 minute to remove excess starch.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/gamja-jorim-step1.png'),
  ('00a2dd53-9a6c-43ae-be17-9b7d8f12bff9', '5c8b95ab-6c0b-40d1-a631-9f2bff8c443c', 2, 'Braise', 'Place the potato cubes in a pan with soy sauce (10ml), sugar (4g), minced garlic (3g), and 0.25 cup (60ml) of water. Bring to a boil over medium-high heat (5 mins), then simmer on medium heat for 10 minutes until the liquid reduces.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/gamja-jorim-step2.png'),
  ('df0ab581-77a6-444a-9eda-4e468a2655ec', '5c8b95ab-6c0b-40d1-a631-9f2bff8c443c', 3, 'Finish & serve', 'Stir constantly in the final 2 minutes until the potato cubes are glossy and glazed. Drizzle with sesame oil (1.6ml) and garnish with sesame seeds (0.3g).', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/gamja-jorim-step3.png'),
  ('e996800a-a068-4682-ae19-1a20f951b9d0', 'f9eac12f-063d-4284-ad12-6f11339e1211', 1, 'Mix the egg batter', 'Crack the eggs (2) into a bowl, add salt (0.75g), finely chopped green onions (15g), and chopped carrots (10g, if using), and beat thoroughly with a fork.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/gyeran-mari-step1.png'),
  ('ab89173e-80bb-44f6-9752-bc82c47f4845', 'f9eac12f-063d-4284-ad12-6f11339e1211', 2, 'Roll the omelette', 'Heat a non-stick pan over medium heat with 1 tsp of oil. Pour a thin layer of the egg mixture into the pan. When nearly set, roll it up from one side to the other. Push the roll to the side, grease the empty space lightly, and pour more egg mixture to attach to the roll. Repeat until all the egg mixture is used.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/gyeran-mari-step2.png'),
  ('f48c268e-5d68-4689-9daa-914a9d572330', 'f9eac12f-063d-4284-ad12-6f11339e1211', 3, 'Slice & serve', 'Let the rolled omelette rest on a cutting board for 1 minute, slice into rounds, and serve.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/gyeran-mari-step3.png'),
  ('1c0ce1e8-bf7e-4520-a644-97713794c3e6', 'ccebc013-8ca5-4da1-a327-9d666575da27', 1, 'Season the zucchini', 'Slice the zucchini (100g) into 0.5cm thick rounds. Season with salt (1.5g), let sit for 5 minutes, and pat dry with paper towels.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/hobak-jeon-step1.png'),
  ('9cae8f04-2b35-47df-bda7-eb6978f23d99', 'ccebc013-8ca5-4da1-a327-9d666575da27', 2, 'Coat in flour & egg', 'Lightly dust each zucchini slice in flour (15g), then dip them into a bowl containing the beaten egg (1).', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/hobak-jeon-step2.png'),
  ('31c413f2-2b19-495f-b518-8f3d7c9ff8c4', 'ccebc013-8ca5-4da1-a327-9d666575da27', 3, 'Pan-fry', 'Heat a pan over medium heat with 1 tsp of oil and fry the coated zucchini slices for 2–3 minutes per side until golden on both sides.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/hobak-jeon-step3.png'),
  ('1981efb4-3821-470a-80f8-d7d0969efd51', 'ccebc013-8ca5-4da1-a327-9d666575da27', 4, 'Serve', 'Serve warm with soy sauce (7.5ml) for dipping.', NULL),
  ('6b84cf95-868d-45a9-b4ae-2baa4701f2c2', '6e70e986-059f-4c64-898f-69126afd2547', 1, 'Boil the beef', 'Place the beef (100g) and green onion (7.5g) in a pot with 2 cups of water, bring to a boil over high heat (5 mins), then simmer on medium heat for 25 minutes until tender. Remove the beef and reserve 0.38 cup (90ml) of the broth.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/jangjorim-step1.png'),
  ('79d43662-dfbf-4de8-8a96-f8cefc8e7b80', '6e70e986-059f-4c64-898f-69126afd2547', 2, 'Shred the beef', 'Let the cooked beef cool slightly, then shred it into thin strips along the grain.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/jangjorim-step2.png'),
  ('c1541d71-d2ce-4773-ab44-2e1cd1e359cd', '6e70e986-059f-4c64-898f-69126afd2547', 3, 'Simmer in sauce', 'Return the shredded beef to the pot with the reserved broth, soy sauce (15ml), sugar (3g), and minced garlic (6g). Simmer on medium-low heat for 10 minutes until the sauce reduces.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/jangjorim-step3.png'),
  ('0da23024-079f-420c-9112-0230b26dc363', '6e70e986-059f-4c64-898f-69126afd2547', 4, 'Add egg & store', 'Add a hard-boiled egg (1, if using) into the pot and cook for 5 more minutes. Store refrigerated for up to a week.', NULL),
  ('81a82007-4b9b-4e8b-95d7-d2db02ab732f', '8e1a0bb3-7a0b-4982-8262-8ea6b3e15247', 1, 'Make the batter', 'In a mixing bowl, combine flour (60g), egg (1), water (120ml), and the chopped fermented kimchi along with a splash of kimchi juice. Add chopped green onions (15g, if using) and mix into a smooth batter.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/kimchi-jeon-quick-step1.png'),
  ('bc91ba72-d472-49df-b495-22f24f5abc9d', '8e1a0bb3-7a0b-4982-8262-8ea6b3e15247', 2, 'Pour into hot pan', 'Heat a pan over medium-high heat with 1.5 tbsp of oil. Pour the batter evenly into the pan to form a thin pancake.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/kimchi-jeon-quick-step2.png'),
  ('c0571e2f-4cb5-4ad7-8e26-5f390b23e811', '8e1a0bb3-7a0b-4982-8262-8ea6b3e15247', 3, 'Fry until golden', 'Cook for 3 minutes per side until crispy and golden brown.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/kimchi-jeon-quick-step3.png'),
  ('d355a7df-8b9a-4ea6-bc9a-2e414e01fbe1', '8e1a0bb3-7a0b-4982-8262-8ea6b3e15247', 4, 'Slice & serve', 'Slice into wedges and serve with soy sauce (7.5ml) for dipping.', NULL),
  ('a6ad6db8-faf3-484b-a5cc-72553d546dd6', 'a3141555-e63d-404e-b7b4-b8a698cdff4c', 1, 'Make the batter', 'In a bowl, mix flour (60g), half of a beaten egg (0.5), water (90ml), salt (0.75g), chopped fermented kimchi (40g), and green onions (38g). Add gochugaru (1g, if using) for extra spice.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/kimchi-pajeon-step1.png'),
  ('9213ef46-f215-48ca-9c70-1502473bbd9d', 'a3141555-e63d-404e-b7b4-b8a698cdff4c', 2, 'Cook the pancake', 'Heat a skillet over medium-high heat with 1.5 tbsp of oil. Pour the pancake batter into the pan and spread it out evenly.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/kimchi-pajeon-step2.png'),
  ('e00d3998-4156-4aed-8add-a8865bbbcdcc', 'a3141555-e63d-404e-b7b4-b8a698cdff4c', 3, 'Flip & crisp', 'Cook for 4 minutes per side until the edges are crispy and golden.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/kimchi-pajeon-step3.png'),
  ('0e6c1cb1-d3c9-4a9d-99e8-5f9507a2bb11', 'a3141555-e63d-404e-b7b4-b8a698cdff4c', 4, 'Slice & serve', 'Slice and serve hot with soy sauce (7.5ml) for dipping.', NULL),
  ('aa095f4b-d33a-4e6f-8004-a7c287bb34de', '8ccac938-0622-432e-af22-0724bea33498', 1, 'Make the batter', 'In a mixing bowl, whisk together flour (60g), half an egg (0.5), water (90ml), and salt (0.75g). Stir in the chopped fermented kimchi and a splash of kimchi juice for enhanced flavor. Add chopped green onions (15g, if using).', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/kimchi-pancake-step1.png'),
  ('5767c7c3-92c3-4344-805c-6dfc9a642045', '8ccac938-0622-432e-af22-0724bea33498', 2, 'Fry the pancake', 'Pour the batter into a hot oiled pan heated to 185°C over medium-high heat. Press flat with a spatula and cook for 3 to 4 minutes per side until golden brown and crispy.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/kimchi-pancake-step2.png'),
  ('f4a66d5d-fcae-45bb-abca-06bb90110171', '8ccac938-0622-432e-af22-0724bea33498', 3, 'Serve', 'Slice into portions and serve with a side of soy sauce for dipping.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/kimchi-pancake-step3.png'),
  ('661f1039-61c4-4bfd-b881-7d101494faf5', 'a990c883-c09b-42e8-b2e6-61b71627059f', 1, 'Soak the beans', 'Soak the black soybeans (45g) in water overnight, then drain.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/kongjorim-step1.png'),
  ('e6df1f0b-513e-4cc7-8614-d1d1229b605b', 'a990c883-c09b-42e8-b2e6-61b71627059f', 2, 'Boil the beans', 'Boil the soaked beans in a pot of water for 30 minutes until tender. Drain the beans, but reserve 0.13 cup (30ml) of the cooking liquid.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/kongjorim-step2.png'),
  ('93f6bb22-a581-4688-a48e-d4a4a06381e1', '212a7194-cee2-4573-98a1-3f1943d98053', 4, 'Garnish & serve', 'Garnish with sesame seeds (1g) and gochugaru (1g, if using) before serving.', NULL),
  ('04d057f6-ecf6-4761-8a24-5d497e910864', 'a990c883-c09b-42e8-b2e6-61b71627059f', 3, 'Braise in sauce', 'Return the beans to the pot along with the soy sauce (11ml), sugar (6g), and the reserved cooking liquid. Simmer on medium-low heat for 10 minutes until the sauce is completely absorbed and the beans are glazed.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/kongjorim-step3.png'),
  ('14e9ae4b-66ff-49c9-99d6-dbf26b7604ea', 'a990c883-c09b-42e8-b2e6-61b71627059f', 4, 'Finish & serve', 'Drizzle with sesame oil (1.2ml) and garnish with sesame seeds (0.25g, if using) before serving.', NULL),
  ('12c86474-6c17-4540-8b81-357cf8860626', '92f112b8-a4fb-46a1-aedf-208d33a3cc82', 1, 'Boil sprouts', 'Place the soybean sprouts (100g) and minced garlic (5g) into a pot with 1.5 cups (375ml) of cold water. Bring to a boil over medium-high heat WITHOUT opening the lid, letting it boil for 5 minutes.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/kongnamul-guk-step1.png'),
  ('66aa0d1b-6060-4a97-a8f5-fc4a3dd13968', '92f112b8-a4fb-46a1-aedf-208d33a3cc82', 2, 'Season the soup', 'Season the broth with soy sauce (7.5ml) and salt (1.5g).', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/kongnamul-guk-step2.png'),
  ('a9851b33-54d9-4f21-96df-e061126167d2', '92f112b8-a4fb-46a1-aedf-208d33a3cc82', 3, 'Garnish & serve', 'Turn off the heat, garnish with chopped green onions (15g), and finish with a drizzle of sesame oil (2.5ml) and gochugaru (1g) if desired.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/kongnamul-guk-step3.png'),
  ('536f6b98-9793-41d6-bf49-b95857a73745', '957c5a47-98bf-4d2f-a290-92473965d1ab', 1, 'Blanch the sprouts', 'Boil the soybean sprouts (150g) in a pot of water for 2 to 3 minutes. Drain immediately and let cool slightly.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/kongnamul-muchim-step1.png'),
  ('3006f75a-db08-4ebc-924a-313ea84b0155', '957c5a47-98bf-4d2f-a290-92473965d1ab', 2, 'Season', 'In a mixing bowl, toss the blanched sprouts with soy sauce (7.5ml), sesame oil (2.5ml), minced garlic (2.5g), and gochugaru (1g, if using).', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/kongnamul-muchim-step2.png'),
  ('f66c5f34-ed05-4f0d-aa87-59843b6a1858', '957c5a47-98bf-4d2f-a290-92473965d1ab', 3, 'Garnish & serve', 'Garnish with chopped green onions (7.5g) and sesame seeds (1g, if using). Serve warm or chilled.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/kongnamul-muchim-step3.png'),
  ('71cb0bf8-f13c-4c6a-a110-590ca82db4d7', 'a8208bdd-1fc4-4df0-a162-81a2a021cf8e', 1, 'Prep the radish', 'Cut the radish (133g) into thick rounds or rectangular chunks.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/mu-jorim-step1.png'),
  ('7a6496bc-02b1-4985-8188-b4d67802f6a2', 'a8208bdd-1fc4-4df0-a162-81a2a021cf8e', 2, 'Braise', 'Place the radish pieces in a pan with soy sauce (15ml), sugar (4g), minced garlic (3g), gochugaru (3g), and 0.17 cup (40ml) of water. Cook on medium heat for 20 minutes until the radish is tender and translucent.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/mu-jorim-step2.png'),
  ('1064d0a6-0f4a-4191-92a0-7befb1a68433', 'a8208bdd-1fc4-4df0-a162-81a2a021cf8e', 3, 'Finish & serve', 'Drizzle with sesame oil (1.6ml) and garnish with chopped green onions (5g) before serving.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/mu-jorim-step3.png'),
  ('2faf3650-8770-43ac-9f75-92679e24b35a', '91c62911-8257-4e45-b402-0b5fe135c22c', 1, 'Julienne the radish', 'Cut the radish (100g) into thin matchstick strips.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/musaengchae-step1.png'),
  ('6db19ddb-0980-4fb0-ae51-3e996d9301fe', '91c62911-8257-4e45-b402-0b5fe135c22c', 2, 'Season & toss', 'In a mixing bowl, toss the radish strips with gochugaru (5g), vinegar (5ml), sugar (1.3g), salt (1g), and minced garlic (1.5g).', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/musaengchae-step2.png'),
  ('6570ea96-45a9-4756-b466-d03dd6f4fa09', '91c62911-8257-4e45-b402-0b5fe135c22c', 3, 'Garnish & serve', 'Garnish with chopped green onions (5g) and sesame seeds (0.3g, if using). Best served chilled.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/musaengchae-step3.png'),
  ('fc15f8fa-1367-41b8-9702-5b41d3570d4b', 'd5abbe91-8249-4695-86c7-54e129c64e8d', 1, 'Prep the cucumber', 'Slice the cucumber (75g) thinly. Lightly sprinkle with salt, let sit for 5 minutes, and squeeze firmly to remove excess moisture.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/oi-muchim-step1.png'),
  ('6c1066ab-cfcd-4ce8-938e-a6538e7e1805', 'd5abbe91-8249-4695-86c7-54e129c64e8d', 2, 'Season & toss', 'In a bowl, mix the cucumbers with gochugaru (5g), soy sauce (7.5ml), sesame oil (2.5ml), minced garlic (2.5g), and sugar (1g).', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/oi-muchim-step2.png'),
  ('16a69075-7b79-40cd-a8a1-8c954e0b4350', 'd5abbe91-8249-4695-86c7-54e129c64e8d', 3, 'Garnish & serve', 'Garnish with chopped green onions (7.5g) and sesame seeds (1g, if using). Best eaten immediately.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/oi-muchim-step3.png'),
  ('91dba1a9-c316-45a6-a348-fe1c6621d1b8', '80dc4fc7-0d77-4645-b6d1-a049a6e9be34', 1, 'Blanch the spinach', 'Boil the spinach (150g) in a pot of water for 30 seconds. Drain immediately and squeeze out excess water with your hands.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/sigeumchi-namul-step1.png'),
  ('fff75014-bd49-46d6-bed6-211116edf98d', '80dc4fc7-0d77-4645-b6d1-a049a6e9be34', 2, 'Season', 'In a bowl, mix the blanched spinach with soy sauce (7.5ml), sesame oil (2.5ml), and minced garlic (2.5g).', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/sigeumchi-namul-step2.png'),
  ('cf7fafc4-6571-4833-8ddd-7a263529a8b2', '80dc4fc7-0d77-4645-b6d1-a049a6e9be34', 3, 'Garnish & serve', 'Garnish with sesame seeds (1g) and chopped green onions (7.5g, if using) before serving.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/sigeumchi-namul-step3.png'),
  ('e55b918d-05b4-4aec-88d5-121a090fc044', '0b2778f1-1403-49e9-96e6-37dbf5335213', 1, 'Make the broth', 'Bring the anchovy broth (375ml) to a boil in a pot over medium-high heat (5 mins), then dissolve the doenjang (11g) into the broth.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/spinach-doenjang-soup-step1.png'),
  ('eb5866ab-e8e5-4384-9ad6-77c04b509a23', '0b2778f1-1403-49e9-96e6-37dbf5335213', 2, 'Add vegetables', 'Add the spinach (100g), minced garlic (2.5g), and diced tofu (50g, if using) into the pot. Cook for 3 minutes.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/spinach-doenjang-soup-step2.png'),
  ('c40d5572-695b-495d-83f6-1d40c8585317', '0b2778f1-1403-49e9-96e6-37dbf5335213', 3, 'Garnish & serve', 'Garnish with chopped green onions (7.5g) and serve hot.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/spinach-doenjang-soup-step3.png'),
  ('5a057c16-dccf-44b7-9e83-958457d45c13', '71688a54-5d35-4915-b473-f55e5ff67a58', 1, 'Mix the egg', 'Whisk the eggs (1.5) with 0.5 cup (125ml) of water and salt (1.5g) until completely combined.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/steamed-egg-step1.png'),
  ('e2bef2a6-87da-47a1-9407-121f6044e9e4', '71688a54-5d35-4915-b473-f55e5ff67a58', 2, 'Steam', 'Pour the mixture into a clay pot or a small oven-safe bowl. Steam over low heat for 10 to 12 minutes until just set.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/steamed-egg-step2.png'),
  ('1b737d55-a8b1-44c5-9d35-074387b24e92', '71688a54-5d35-4915-b473-f55e5ff67a58', 3, 'Garnish & serve', 'Top with chopped green onions (7.5g) and a light drizzle of sesame oil (1.2ml). Serve immediately.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/steamed-egg-step3.png'),
  ('c548dca5-55c5-4a7f-b425-f8be3c355ae7', '02ddf148-dcf1-41cc-9c51-cab4bb0b04d9', 1, 'Blanch the sprouts', 'Blanch the mung bean sprouts (150g) in boiling water for 1 minute. Drain immediately and cool with cold water.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/sukju-namul-step1.png'),
  ('8c8829e4-b142-4063-bdd6-214c3bdf7625', '02ddf148-dcf1-41cc-9c51-cab4bb0b04d9', 3, 'Garnish & serve', 'Garnish with chopped green onions (7.5g) and sesame seeds (1g, if using) before serving.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/sukju-namul-step3.png'),
  ('086ce173-3bf7-4803-ac25-6a719e26994f', '34d7768d-3f80-4e6d-b82f-b8fef8cc9d94', 1, 'Marinate the chicken', 'Season the boneless skinless chicken thigh pieces (250g) with salt (2g), minced garlic (5g), soy sauce (7.5ml, if using), and sesame oil (2.5ml, if using). Let it rest at room temperature for 15 minutes.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/dak-twigim-step1.png'),
  ('53276b47-ef60-4a15-9af8-714bd8e314a5', '34d7768d-3f80-4e6d-b82f-b8fef8cc9d94', 2, 'Coat with cornstarch', 'Coat the marinated chicken pieces thoroughly in cornstarch (40g) until fully covered.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/dak-twigim-step2.png'),
  ('8e57d185-5794-4d5f-be9b-c72be672165c', '34d7768d-3f80-4e6d-b82f-b8fef8cc9d94', 3, 'Deep-fry', 'Heat cooking oil in a deep pan to 170°C. Fry the coated chicken pieces for 12 minutes until golden brown and completely crispy. Remove and drain on a wire rack or paper towels.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/dak-twigim-step3.png'),
  ('85a06be5-dbd7-40f8-a1ec-d5d3b92b8919', '34d7768d-3f80-4e6d-b82f-b8fef8cc9d94', 4, 'Garnish & serve', 'Garnish with sesame seeds (1g) and chopped green onions (7.5g) before serving.', NULL),
  ('912c58da-3700-40f5-abdd-f1a167286778', '3b551d41-b58f-4874-a1dd-405cec530894', 1, 'Make the broth', 'Bring the anchovy broth (330ml) to a rolling boil in a pot over medium-high heat (5 mins) with minced garlic (3.3g) and soy sauce (10ml).', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/eomuk-tang-step1.png'),
  ('57fbaf3a-d31d-4f0a-a969-9936523c67b2', '3b551d41-b58f-4874-a1dd-405cec530894', 2, 'Simmer the fish cakes', 'Fold and thread the fish cake sheets (100g) onto wooden skewers, then submerge them into the boiling broth and simmer on medium heat for 10 minutes.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/eomuk-tang-step2.png'),
  ('e26f38fc-86dc-46b2-a2c1-0b0ae747be96', '3b551d41-b58f-4874-a1dd-405cec530894', 3, 'Garnish & serve', 'Garnish with chopped green onions (10g) and serve hot with the broth in a cup. Add gochugaru (1g) or sesame oil (1.6ml) if desired.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/eomuk-tang-step3.png'),
  ('28b65508-db66-491d-af8b-cf5920e6b047', 'c20dfa40-5e76-46e8-a0bf-bff0a2206d71', 1, 'Make the filling', 'In a mixing bowl, combine the ground pork (67g), crumbled firm tofu (33g), minced garlic (3.3g), soy sauce (5ml), sesame oil (1.6ml), chopped green onions (10g), and cabbage (33g, if using) until well blended to make the filling.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/gunmandu-step1.png'),
  ('af7222de-3366-48b1-ace9-0da9e4703a49', 'c20dfa40-5e76-46e8-a0bf-bff0a2206d71', 2, 'Wrap the dumplings', 'Place a small spoonful of filling in the center of each dumpling wrapper, wet the edges with water, fold in half, and pinch the edges firmly to seal.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/gunmandu-step2.png'),
  ('40e929bc-35ee-4c5f-8306-7e29fe1a64e5', 'c20dfa40-5e76-46e8-a0bf-bff0a2206d71', 3, 'Pan-fry', 'Heat 1 tbsp of oil in a skillet over medium-high heat (180°C). Place the dumplings flat-side down and pan-fry for 3 minutes until the bottoms turn golden brown.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/gunmandu-step3.png'),
  ('a986506e-391f-4923-ae7e-f8953ceb280d', 'c20dfa40-5e76-46e8-a0bf-bff0a2206d71', 4, 'Steam to finish', 'Carefully pour 0.25 cup (60ml) of water into the skillet, cover with a lid immediately, and steam on medium heat for 5 minutes until the water evaporates and the filling is fully cooked.', NULL),
  ('5ccfda6f-c688-4de0-9957-390296cb2df8', 'bba92518-8519-43ed-a378-14126650b10a', 1, 'Make the dough', 'In a bowl, mix flour (60g), yeast (1g), sugar (1g), salt (0.3g), and warm water (45ml) to form a smooth dough. Cover and let it rest at room temperature for 1 hour to rise.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/hotteok-step1.png'),
  ('43d095a8-246b-48c2-b1a2-f3615727b0d0', 'bba92518-8519-43ed-a378-14126650b10a', 2, 'Make the filling', 'In a small bowl, prepare the filling by mixing brown sugar (12g), cinnamon (0.75g), sesame seeds (3.75g), and crushed peanuts (3.75g, if using).', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/hotteok-step2.png'),
  ('a35d5c35-d68a-4529-ac98-32b34e35c2b3', 'bba92518-8519-43ed-a378-14126650b10a', 3, 'Shape & fill', 'Punch down the risen dough to release air, divide into a portion, flatten it on your palm, and place a spoonful of the sugar filling in the center. Bring the edges up and pinch tightly to seal the ball completely.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/hotteok-step3.png'),
  ('e97fbca5-b5eb-49be-9581-198b498ce077', 'bba92518-8519-43ed-a378-14126650b10a', 4, 'Pan-fry & flatten', 'Heat a greased pan over medium heat (170°C). Place the dough ball seam-side down, let it cook for 1 minute, then flatten it firmly using a spatula. Pan-fry for 2-3 minutes per side until golden brown and crispy.', NULL),
  ('5fb6ea64-20b6-4982-9266-279f8523424d', 'ba971f5e-a8cf-44ac-b435-36ac62ec5758', 1, 'Slice the soondae', 'Slice the soondae (150g) into bite-sized rounds (about 1.5cm thick).', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/soondae-bokkeum-step1.png'),
  ('f393cbb9-7e53-49b1-9778-3520d28660d1', 'ba971f5e-a8cf-44ac-b435-36ac62ec5758', 2, 'Stir-fry aromatics', 'Heat a pan over high heat (190°C) with 1 tsp of oil. Stir-fry the minced garlic (5g) and sliced onions (40g) for 2 minutes until fragrant.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/soondae-bokkeum-step2.png'),
  ('958bc535-9354-40f2-95e2-0dbeb85e4cc5', 'ba971f5e-a8cf-44ac-b435-36ac62ec5758', 3, 'Add soondae & sauce', 'Add the sliced soondae, gochujang (15g), gochugaru (3.5g), and soy sauce (7.5ml) into the pan. Stir-fry gently for 4-5 minutes, being careful not to break the soondae pieces.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/soondae-bokkeum-step3.png'),
  ('eef3a0e4-2c1e-45e0-83f7-08f0db78638a', 'ba971f5e-a8cf-44ac-b435-36ac62ec5758', 4, 'Finish & serve', 'Toss with chopped green onions (15g) and a drizzle of sesame oil (2.5ml, if using) before removing from heat and serving.', NULL),
  ('d90d0456-c800-41c5-8bf5-e331298297fe', '97566d15-ec87-40c7-aaa3-4c6ca57b2780', 1, 'Make the sauce', 'In a pan, mix gochujang (15g), gochugaru (3.5g), sugar (6g), and soy sauce (7.5ml) with 1 cup (250ml) of water.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/sundae-tteokbokki-step1.png'),
  ('3052e0f5-179c-49f6-ae45-2e8f7690367f', '97566d15-ec87-40c7-aaa3-4c6ca57b2780', 2, 'Cook the rice cakes', 'Bring the sauce to a boil over medium-high heat (5 mins), then add the rice cakes (125g) and sliced fish cakes (50g, if using). Cook for 10 minutes, stirring frequently until the rice cakes soften.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/sundae-tteokbokki-step2.png'),
  ('47e02ba1-b284-47bd-bf06-bff0d39d25cd', '97566d15-ec87-40c7-aaa3-4c6ca57b2780', 3, 'Add soondae', 'Add the sliced soondae (75g) into the pan and continue cooking for 3 more minutes until heated through and coated in the thick sauce.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/sundae-tteokbokki-step3.png'),
  ('bc719454-a51d-42df-b6fc-66145c96aca7', '97566d15-ec87-40c7-aaa3-4c6ca57b2780', 4, 'Garnish & serve', 'Garnish with chopped green onions (15g) and serve immediately.', NULL),
  ('6f4c5769-a21b-4456-8ba4-0b0ef0eaf2ef', '0cac7965-de6f-4a6a-bc1d-083c788d93b7', 1, 'Make the sauce', 'In a pan, combine gochujang (15g), gochugaru (3.5g), sugar (6g), soy sauce (7.5ml), and 1 cup (250ml) of water. Stir well.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/tteokbokki-step1.png'),
  ('e35ca81d-cd13-466d-b729-d8f358997e06', '0cac7965-de6f-4a6a-bc1d-083c788d93b7', 2, 'Cook rice cakes', 'Bring the sauce mixture to a boil over medium-high heat (5 mins). Add the rice cakes (150g) and cubed Spam (50g, if using).', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/tteokbokki-step2.png'),
  ('4e4c2237-e74e-41a5-92a5-f0336ae59ce9', '0cac7965-de6f-4a6a-bc1d-083c788d93b7', 3, 'Simmer until thick', 'Cook on medium heat (170°C) for 10 to 15 minutes, stirring frequently to prevent the rice cakes from sticking to the bottom of the pan.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/tteokbokki-step3.png'),
  ('238e88c3-c7d4-410c-8139-732b90b82e39', '0cac7965-de6f-4a6a-bc1d-083c788d93b7', 4, 'Finish & serve', 'Once the sauce thickens and tightly coats the chewy rice cakes, remove from heat. Garnish with chopped green onions (15g) and a hard-boiled egg (1, if using).', NULL),
  ('02127f54-b447-4e20-a8f7-8d996cc408fd', '3be41c63-0c18-45a5-a22c-bf443d814237', 1, 'Make the batter', 'In a bowl, mix flour (40g), a third of a beaten egg (0.33), 0.25 cup (60ml) of cold water, and salt (0.5g) to create a light tempura-style batter.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/twigim-step1.png'),
  ('57f94633-02d4-4fff-8f35-f632b74cc374', '3be41c63-0c18-45a5-a22c-bf443d814237', 2, 'Coat the vegetables', 'Dip the sliced zucchini (50g), onions (40g), and fish cake strips (50g) into the batter to coat evenly.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/twigim-step2.png'),
  ('834f736f-85f8-4ee8-b58d-83c10f934830', '3be41c63-0c18-45a5-a22c-bf443d814237', 3, 'Fry until crispy', 'Deep-fry or shallow-fry the coated items in hot oil heated to 170°C for 4 minutes until golden and crisp.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/twigim-step3.png'),
  ('af4d57fb-8ae7-4988-a146-54e4d89c2110', '3be41c63-0c18-45a5-a22c-bf443d814237', 4, 'Drain & serve', 'Drain on paper towels and serve hot with a side of soy sauce (5ml) for dipping.', NULL),
  ('579fb3f1-331a-41d1-a0ee-15967159572f', '9b1e634c-040e-4e1d-9594-f65452918e2e', 1, 'Blanch the broccoli', 'Cut the broccoli into bite-sized florets. Bring a pot of water to a rolling boil over high heat (5 mins), add the broccoli, and blanch for 2 minutes.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/broccoli-muchim-step1.png'),
  ('f13bf7ec-34e1-418d-8d83-2d8e9d40c0cf', '9b1e634c-040e-4e1d-9594-f65452918e2e', 2, 'Drain & cool', 'Drain the broccoli immediately and rinse under cold water to stop the cooking process; squeeze gently to remove excess moisture.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/broccoli-muchim-step2.png'),
  ('0e83d9e6-1e15-47fa-bb13-c54cefaa40aa', '9b1e634c-040e-4e1d-9594-f65452918e2e', 3, 'Make the dressing', 'In a mixing bowl, combine soy sauce (7.5ml), sesame oil (2.5ml), minced garlic (5g), sugar (1.5g, if using), and gochugaru (1g, if using).', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/broccoli-muchim-step3.png'),
  ('7c7dfdaa-44c7-4df8-b15b-c59cc5046f3a', '9b1e634c-040e-4e1d-9594-f65452918e2e', 4, 'Toss & coat', 'Add the blanched broccoli to the dressing and toss thoroughly until evenly coated.', NULL),
  ('692f17d6-adad-47da-ad71-8a20f5e887ea', '9b1e634c-040e-4e1d-9594-f65452918e2e', 5, 'Garnish & serve', 'Garnish with sesame seeds (1g) and serve.', NULL),
  ('66538572-6f08-438d-8ec9-0289514677f6', 'f2aa82c8-3389-4c09-9625-c929e6508f9e', 1, 'Prep the chives', 'Wash the garlic chives (100g) and cut them into 5cm lengths.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/buchu-jeon-step1.png'),
  ('ad43b238-7b43-403f-b739-9bf7be38a20a', 'f2aa82c8-3389-4c09-9625-c929e6508f9e', 2, 'Make the batter', 'In a mixing bowl, whisk together flour (30g), egg (1), water (60ml), and salt (0.75g) until a smooth batter forms. Add the chopped chives into the batter and mix well.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/buchu-jeon-step2.png'),
  ('3a1e1eec-2ca3-46a7-a14d-fbe504d6fd4d', 'f2aa82c8-3389-4c09-9625-c929e6508f9e', 3, 'Pan-fry', 'Heat a skillet over medium-high heat (185°C) with 1 tbsp of oil. Pour the chive and batter mixture into the pan, spreading it out into a thin, even circle.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/buchu-jeon-step3.png'),
  ('d6237748-4733-4cdb-a981-854712ed902e', 'f2aa82c8-3389-4c09-9625-c929e6508f9e', 4, 'Cook both sides', 'Pan-fry for 3 to 4 minutes per side until golden brown and crispy on both sides.', NULL),
  ('937be82e-93a1-4ce9-88eb-f7c40d1ab72c', 'f2aa82c8-3389-4c09-9625-c929e6508f9e', 5, 'Make dipping sauce', 'Serve warm with a dipping sauce made from soy sauce (7.5ml), sesame oil (2.5ml), and gochugaru (1g, if using).', NULL),
  ('2ff08b48-8348-4010-ba9c-b2c6c7241677', '212a7194-cee2-4573-98a1-3f1943d98053', 1, 'Prep the cabbage', 'Shred the cabbage (100g) thinly. Blanch briefly in boiling water for 30 seconds or keep raw for a crunchy texture, then drain completely.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/cabbage-doenjang-muchim-step1.png')
INSERT INTO pantry_recipe_steps ("id", "recipe_id", "step_order", "title", "description", "image_url") VALUES
  ('b570f9a1-8645-44ee-8a55-29faa819725d', '212a7194-cee2-4573-98a1-3f1943d98053', 2, 'Make the dressing', 'In a mixing bowl, combine doenjang (7.5g), sesame oil (2.5ml), minced garlic (2.5g), and vinegar (2.5ml) to create the dressing.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/cabbage-doenjang-muchim-step2.png'),
  ('eaa2f569-8098-4ca3-97bd-9e5d57dfbbe4', '212a7194-cee2-4573-98a1-3f1943d98053', 3, 'Toss & coat', 'Toss the shredded cabbage with the doenjang dressing until fully coated.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/cabbage-doenjang-muchim-step3.png'),
  ('d5c0085d-854f-4ada-bc05-07009461b58f', 'aa58e15d-c5f2-4af7-b3bf-cc5df7e27a7c', 1, 'Prep the potato', 'Peel and cube the potato (100g) into bite-sized pieces.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/gamja-guk-step1.png'),
  ('6c701a45-174c-42ef-bf40-ce6f6f38537a', 'aa58e15d-c5f2-4af7-b3bf-cc5df7e27a7c', 2, 'Make the broth', 'In a pot, bring the anchovy broth (375ml) to a boil over medium-high heat (5 mins). Dissolve the doenjang (7.5g) and minced garlic (2.5g) into the broth.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/gamja-guk-step2.png'),
  ('74109fc4-3a7e-41bc-ab4f-95b9f979e575', 'aa58e15d-c5f2-4af7-b3bf-cc5df7e27a7c', 3, 'Cook the potato', 'Add the cubed potatoes to the pot, reduce heat to medium (170°C), and simmer for 12 minutes until the potatoes are tender.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/gamja-guk-step3.png'),
  ('bde1ab17-0f43-4722-a20b-79191582bd77', 'aa58e15d-c5f2-4af7-b3bf-cc5df7e27a7c', 4, 'Season', 'Season with salt (0.75g, if needed).', NULL),
  ('920dad64-6f0e-4b75-b936-ea8d13fd14c7', 'aa58e15d-c5f2-4af7-b3bf-cc5df7e27a7c', 5, 'Garnish & serve', 'Garnish with chopped green onions (7.5g) and a drizzle of sesame oil (2.5ml, if using) before serving.', NULL),
  ('60978423-5029-4c96-986e-72195a59f0bd', '353a418e-4a8d-4119-952a-ac38a574d44d', 1, 'Slice the zucchini', 'Slice the zucchini (100g) into half-moons.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/hobak-doenjang-muchim-step1.png'),
  ('77044183-2cef-4c23-9d99-dee979918a38', '353a418e-4a8d-4119-952a-ac38a574d44d', 2, 'Sauté the zucchini', 'Heat a pan over medium-high heat (180°C) with 1 tsp of oil, add the zucchini slices, and sauté for 3 to 4 minutes until softened. Remove from heat and let cool slightly.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/hobak-doenjang-muchim-step2.png'),
  ('d43d6396-8d61-4462-9a88-cffe375f25ea', '353a418e-4a8d-4119-952a-ac38a574d44d', 3, 'Make the dressing', 'In a bowl, mix together the doenjang (7.5g), sesame oil (2.5ml), and minced garlic (2.5g).', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/hobak-doenjang-muchim-step3.png'),
  ('f7912f34-e15a-4c4e-9705-9256fd56cac2', '353a418e-4a8d-4119-952a-ac38a574d44d', 4, 'Toss & coat', 'Gently toss the sautéed zucchini with the doenjang mixture.', NULL),
  ('83f640a1-faae-4858-8ec4-5f51ff2d35ad', '353a418e-4a8d-4119-952a-ac38a574d44d', 5, 'Garnish & serve', 'Garnish with chopped green onions (7.5g) and sesame seeds (1g, if using).', NULL),
  ('df8c1366-acec-4dde-a13e-1b28e3af9320', '4077385d-6e8d-4e17-b605-d4acfde8b31d', 1, 'Salt the cabbage', 'Cut the napa cabbage portion (100g) into bite-sized pieces and salt between the leaves using a portion of the salt (18g). Let it sit at room temperature for 2 hours, turning occasionally, then rinse thoroughly with cold water and drain well in a colander.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/homemade-kimchi-step1.png'),
  ('571dc374-d847-42fc-9be8-48bcaee6d829', '4077385d-6e8d-4e17-b605-d4acfde8b31d', 2, 'Make the paste', 'In a small mixing bowl, combine gochugaru (10g), minced garlic (5g), grated ginger (1.5g), fish sauce (3ml), and sugar (0.5g, if using) into a smooth paste.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/homemade-kimchi-step2.png'),
  ('28528a09-d378-4354-a93f-c2156b8827e9', '4077385d-6e8d-4e17-b605-d4acfde8b31d', 3, 'Coat the cabbage', 'In a large bowl, toss the drained cabbage and chopped green onions (7.5g) with the chili paste, ensuring every leaf is thoroughly coated.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/homemade-kimchi-step3.png'),
  ('52944663-d3c4-46f5-b87f-2ae0b000a5d8', '4077385d-6e8d-4e17-b605-d4acfde8b31d', 4, 'Ferment & store', 'Pack the kimchi tightly into a clean glass jar. Leave it to ferment at room temperature for 1 to 2 days, then transfer it to the refrigerator.', NULL),
  ('2fd3e7fa-0b2a-481d-8c67-47902dcbe089', '87299c9e-5c7d-46a6-91a1-ff282e818aac', 1, 'Cook the noodles', 'Bring a pot of water to a boil over high heat (5 mins), add the glass noodles (75g), and cook for 3 minutes. Drain thoroughly and cut with scissors.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/japchae-namul-bowl-step1.png'),
  ('23c93d75-658e-4d8d-bcc9-1e33dd00c05f', '87299c9e-5c7d-46a6-91a1-ff282e818aac', 2, 'Blanch vegetables', 'In the same boiling water, blanch the spinach (50g) and bean sprouts (50g) separately for 30 seconds each, rinse under cold water, and squeeze out all excess moisture.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/japchae-namul-bowl-step2.png'),
  ('2ee91577-aa0b-4bcb-9617-0ae2e2a121b2', '87299c9e-5c7d-46a6-91a1-ff282e818aac', 3, 'Sauté carrots', 'If using carrots (25g), sauté them in a pan with a drop of oil over medium heat (175°C) for 2 minutes.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/japchae-namul-bowl-step3.png'),
  ('82aba97e-3a16-41e9-bd96-a45a408eedb5', '87299c9e-5c7d-46a6-91a1-ff282e818aac', 4, 'Season & toss', 'In a large bowl, combine the cooked noodles, spinach, bean sprouts, and carrots with soy sauce (15ml), sesame oil (7.5ml), and minced garlic (2.5g). Toss thoroughly.', NULL),
  ('68929f1f-6c37-4ad3-aafa-a3b64f7d97eb', '87299c9e-5c7d-46a6-91a1-ff282e818aac', 5, 'Plate & garnish', 'Plate the mixture and garnish with sesame seeds (1g, if using).', NULL),
  ('a7deca39-173f-40f1-a108-069880037009', '21c922d8-d13e-4e64-a4e4-129751d0f062', 1, 'Prep the radish', 'Cut the Korean radish (100g) into thin bite-sized rectangular cubes.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/mu-doenjang-guk-step1.png'),
  ('03f48cd8-9c02-4e64-a398-a0c36f196137', '21c922d8-d13e-4e64-a4e4-129751d0f062', 2, 'Make the broth', 'Bring the anchovy broth (375ml) to a boil in a pot over medium-high heat (5 mins). Dissolve the doenjang (11g) into the broth.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/mu-doenjang-guk-step2.png'),
  ('2920f008-62d0-4787-bae5-8a1f1fa5a9ff', '21c922d8-d13e-4e64-a4e4-129751d0f062', 3, 'Cook the radish', 'Add the cubed radish and minced garlic (2.5g) to the pot, reduce heat to medium (170°C), and simmer for 12 minutes until the radish is tender.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/mu-doenjang-guk-step3.png'),
  ('55128a76-47ae-4769-8446-2fa74e104dc0', '21c922d8-d13e-4e64-a4e4-129751d0f062', 4, 'Add tofu & season', 'Add the diced firm tofu (50g, if using) and cook for 2 more minutes. Season with salt (0.75g) if additional seasoning is needed.', NULL),
  ('c814a714-39f2-4239-ba6a-1cad3fd5a4ba', '21c922d8-d13e-4e64-a4e4-129751d0f062', 5, 'Garnish & serve', 'Garnish with chopped green onions (7.5g) and serve hot.', NULL),
  ('50472172-d2bd-4275-9203-723dafd519c5', '4484bb3d-ac89-4869-9610-8dd1f14b7cf0', 1, 'Salt the cucumber', 'Slice the cucumber (100g) thinly. Toss with salt (1.5g) in a bowl and let sit for 5 minutes. Squeeze the cucumber firmly to remove excess moisture.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/oi-naengchae-step1.png'),
  ('3c387feb-2a5e-47fa-b11d-b91dd977d4eb', '4484bb3d-ac89-4869-9610-8dd1f14b7cf0', 2, 'Make the dressing', 'In a small mixing bowl, combine vinegar (15ml), sugar (6g), sesame oil (2.5ml), and gochugaru (1g, if using) until the sugar dissolves.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/oi-naengchae-step2.png'),
  ('1b2a6390-fd3c-4938-be93-0a58948680b8', '4484bb3d-ac89-4869-9610-8dd1f14b7cf0', 3, 'Toss & dress', 'Toss the seasoned, drained cucumber slices with the tangy-sweet dressing.', 'https://eecvvgkihtcgfikaimao.supabase.co/storage/v1/object/public/pantry-recipe-images/oi-naengchae-step3.png'),
  ('856eb519-2352-4830-801b-6cf52829dd9d', '4484bb3d-ac89-4869-9610-8dd1f14b7cf0', 4, 'Garnish & serve', 'Garnish with sesame seeds (1g, if using) and serve immediately while chilled.', NULL)
